const GRADE_LEVELS=['G1S','G1D','G2','G3'];
const LEGACY_GRADE_MAP={'사원':'G1S','선임':'G1D','책임':'G2','팀장':'G3'};
function normalizeGrade(value){return GRADE_LEVELS.includes(value)?value:(LEGACY_GRADE_MAP[value]||'G1S')}
const TASK_DIFFICULTIES=['하','중','상','최상'];
const LEGACY_DIFFICULTY_MAP={'G1S':'하','G1D':'중','G2':'상','G3':'최상','사원':'하','선임':'중','책임':'상','팀장':'최상'};
function normalizeDifficulty(value){return TASK_DIFFICULTIES.includes(value)?value:(LEGACY_DIFFICULTY_MAP[value]||'중')}
Object.entries(LEGACY_GRADE_MAP).forEach(([legacy,grade])=>{if(GRADE_DEFAULTS[legacy])GRADE_DEFAULTS[grade]=GRADE_DEFAULTS[legacy]});
Object.keys(LEGACY_GRADE_MAP).forEach(legacy=>delete GRADE_DEFAULTS[legacy]);
Object.entries(LEGACY_GRADE_MAP).forEach(([legacy,grade])=>{GRADE_DEFAULTS[legacy]=GRADE_DEFAULTS[grade]});
let data=JSON.parse(localStorage.getItem('rr-board-data')||'null')||JSON.parse(JSON.stringify(seed));
window.RR_APP={getData:()=>data,setData:next=>{data=next}};
data.members=(Array.isArray(data.members)?data.members:[]).map(member=>({...member,level:normalizeGrade(member.level)}));
data.tasks=(Array.isArray(data.tasks)?data.tasks:[]).map(task=>({...task,requiredLevel:normalizeGrade(task.requiredLevel),difficulty:normalizeDifficulty(task.difficulty)}));
