async function cloudRequest(table,method='POST',payload=null,query=''){const url=SUPABASE_URL||window.RR_SUPABASE_URL||'';const key=SUPABASE_ANON_KEY||window.RR_SUPABASE_ANON_KEY||'';if(!url||!key)return;const response=await fetch(`${url}/rest/v1/${table}${query}`,{method,headers:{apikey:key,Authorization:`Bearer ${key}`,'Content-Type':'application/json',Prefer:'return=minimal'},body:payload?JSON.stringify(payload):undefined});if(!response.ok)throw new Error(`Supabase ${response.status}`);return response}
function save(){localStorage.setItem('rr-board-data',JSON.stringify(data));window.RR_SUPABASE_SYNC?.schedule(data);}
function toast(msg){const e=$('#toast');e.textContent=msg;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2300)}
function heading(title,eyebrow,subtitle,action=''){return `<div class="view-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${action}</div>`}
function workload(name){return data.members.find(m=>m.name===name)?.workload||0}
function taskCard(t){const due=t.due?.slice(5).replace('-','.');return `<article class="task-tile ${t.status}"><div class="task-head"><span class="status ${t.status}">${t.status==='assigned'?'배정 완료':'담당 미정'}</span><span class="priority">${t.estimatedHours||0}h</span></div><h3>${esc(t.title)}</h3><p class="task-meta">${esc(t.description)}</p><div class="task-tags">${(t.collaborators||[]).map(c=>`<span>협업 · ${esc(c)}</span>`).join('')||'<span>협업 부서 미지정</span>'}</div><div class="task-footer"><span class="owner-chip"><span class="mini-avatar">${t.owner==='미정'?'?':esc(t.owner[0])}</span>${esc(t.owner)}${t.owner!=='미정'?`<small>부하 ${workload(t.owner)}%</small>`:''}</span><span class="date">마감 ${due}</span></div>${t.owner!=='미정'?`<button class="satisfaction-btn" onclick="openSatisfaction(${t.id})">업무 만족도 남기기</button>`:''}</article>`}
function dashboard(){const assigned=data.tasks.filter(t=>t.status!=='unassigned').length;const rate=Math.round(assigned/data.tasks.length*100)||0;const avg=assigned? '2.4':'—';return `<section class="view">${heading('R&R 현황판','WEEKLY SNAPSHOT','모호한 업무를 등록하고, 적합한 담당자와 기한을 연결합니다.','<button class="btn" onclick="go(\'tasks\');setTimeout(openTaskForm,0)">+ 업무 올리기</button>')}<div class="metric-grid"><div class="metric-card"><div class="metric-top"><span>담당 배정률</span><span>목표 80%</span></div><div class="metric-value">${rate}<em>%</em></div><div class="metric-note">미배정 ${data.tasks.length-assigned}건 · 지난주 대비 +14%p</div><span class="trend">↗ 좋아지고 있어요</span></div><div class="metric-card"><div class="metric-top"><span>배정까지 평균 시간</span><span>최근 30일</span></div><div class="metric-value">${avg}<em>일</em></div><div class="metric-note">기준선 대비 0.8일 단축</div><span class="trend">↘ -25%</span></div><div class="metric-card"><div class="metric-top"><span>참여 인원</span><span>실시간</span></div><div class="metric-value">${data.members.length}<em>명</em></div><div class="metric-note">이번 주 기록 참여자 ${Math.min(data.members.length,6)}명</div><span class="trend">● 접속 중</span></div></div><div class="dashboard-grid"><div class="panel"><div class="panel-header"><div><div class="panel-title">담당 배정 추이</div><div class="panel-desc">목표 80% 대비 주간 실적</div></div><span class="chart-legend">● 배정 비율</span></div><div class="chart"><div class="chart-lines"><i></i><i></i><i></i><i></i><i></i></div><svg viewBox="0 0 600 150" preserveAspectRatio="none"><path d="M0 123 C90 118 115 108 172 112 S245 93 300 98 S385 72 430 77 S520 40 600 43 L600 150 L0 150Z" fill="#0f4c81" fill-opacity=".12"/><path d="M0 123 C90 118 115 108 172 112 S245 93 300 98 S385 72 430 77 S520 40 600 43" fill="none" stroke="#0f4c81" stroke-width="3"/><circle cx="600" cy="43" r="4" fill="#f4b85f"/></svg><div class="axis"><span>7/20</span><span>7/27</span><span>8/03</span><span>8/10</span><span>이번 주</span></div></div></div><div class="panel"><div class="panel-header"><div><div class="panel-title">역할 지도</div><div class="panel-desc">구성원별 담당 영역</div></div><span class="chart-legend">${assigned}건 배정</span></div><div class="owner-list">${data.members.slice(0,4).map(m=>`<div class="owner"><span class="owner-avatar">${esc(m.name[0])}</span><div class="owner-info"><strong>${esc(m.name)}</strong><small>${m.skills.slice(0,2).join(' · ')}</small></div><span class="owner-count">${data.tasks.filter(t=>t.owner===m.name).length}</span></div>`).join('')}</div></div></div><div class="section-row"><h2>업무 항목 현황</h2><a onclick="go('tasks')">전체 보기 →</a></div><div class="task-grid">${data.tasks.map(taskCard).join('')}</div></section>`}
function dashboardExtras(){const urgent=data.tasks.filter(t=>t.status==='unassigned'||(t.due&&t.due<='2026-08-21')).slice(0,3);return `<div class="dashboard-extras"><div class="panel"><div class="panel-header"><div><div class="panel-title">지금 확인할 일</div><div class="panel-desc">업무 누락과 기한 임박 항목을 먼저 확인하세요.</div></div><button class="text-btn" onclick="go('tasks')">업무판 열기 →</button></div><div class="attention-list">${urgent.map(t=>`<button class="attention-item" onclick="go('tasks')"><span class="attention-dot ${t.status}"></span><span><b>${esc(t.title)}</b><small>${t.status==='unassigned'?'담당자 미지정':'마감 '+t.due}</small></span><span>›</span></button>`).join('')||'<div class="empty">주의할 업무가 없습니다.</div>'}</div></div><div class="panel"><div class="panel-header"><div><div class="panel-title">팀 업무부하</div><div class="panel-desc">배정 전 후보를 고를 때 참고합니다.</div></div><button class="text-btn" onclick="go('admin')">관리 →</button></div><div class="load-list">${data.members.map(m=>{const color=m.workload>=80?'high':m.workload>=60?'mid':'ok';return `<div class="load-row"><div class="load-person"><span class="owner-avatar">${esc(m.name[0])}</span><b>${esc(m.name)}</b><small>${m.level}</small></div><div class="load-bar"><span class="${color}" style="width:${m.workload}%"></span></div><strong class="load-value ${color}">${m.workload}%</strong></div>`}).join('')}</div></div></div>`}
function adminExtras(){const total=data.satisfaction.length;const fit=total?Math.round(data.satisfaction.filter(x=>x.fit==='적절').length/total*100):0;const load=total?Math.round(data.satisfaction.filter(x=>x.load==='과다').length/total*100):0;return `<div class="dashboard-extras"><div class="panel"><div class="panel-header"><div><div class="panel-title">배정 후 만족도</div><div class="panel-desc">업무 배정이 적절했는지 구성원 응답을 요약합니다.</div></div></div><div class="mini-stats"><div><strong>${total}</strong><small>응답 수</small></div><div><strong>${fit}%</strong><small>적절 응답</small></div><div><strong>${load}%</strong><small>과다 응답</small></div></div></div><div class="panel"><div class="panel-header"><div><div class="panel-title">운영 체크리스트</div><div class="panel-desc">주간 점검 때 빠뜨리지 않을 항목</div></div></div><div class="check-list"><span>✓ 미배정 업무 확인</span><span>✓ 기한 미입력 업무 확인</span><span>✓ 부하 80% 이상 구성원 확인</span><span>✓ 만족도 의견 반영</span></div></div></div>`}
function filteredTasks(){return data.tasks.filter(t=>(!taskQuery||`${t.title} ${t.description} ${(t.collaborators||[]).join(' ')}`.toLowerCase().includes(taskQuery.toLowerCase()))&&(taskStatus==='all'||t.status===taskStatus)&&(taskOwner==='all'||t.owner===taskOwner)).sort((a,b)=>taskSort==='owner'?a.owner.localeCompare(b.owner):taskSort==='new'?b.id-a.id:(a.due||'9999').localeCompare(b.due||'9999'))}
function tasks(){const list=filteredTasks();return `<section class="view">${heading('업무 항목','R&R BOARD','담당이 모호하거나 겹치는 일을 올리고, 적합한 인원을 추천받아 배정합니다.','<button class="btn" onclick="openTaskForm()">+ 새 업무 올리기</button>')}<div class="board-toolbar"><div class="search-box"><span>⌕</span><input id="taskSearch" value="${esc(taskQuery)}" placeholder="업무명, 설명, 협업 부서 검색" aria-label="업무 검색"></div><select id="taskStatusFilter" aria-label="상태 필터"><option value="all" ${taskStatus==='all'?'selected':''}>모든 상태</option><option value="unassigned" ${taskStatus==='unassigned'?'selected':''}>담당 미정</option><option value="assigned" ${taskStatus==='assigned'?'selected':''}>배정 완료</option></select><select id="taskOwnerFilter" aria-label="담당자 필터"><option value="all">모든 담당자</option>${data.members.map(m=>`<option value="${esc(m.name)}" ${taskOwner===m.name?'selected':''}>${esc(m.name)}</option>`).join('')}</select><select id="taskSort" aria-label="정렬"><option value="due" ${taskSort==='due'?'selected':''}>마감 임박순</option><option value="new" ${taskSort==='new'?'selected':''}>최근 등록순</option><option value="owner" ${taskSort==='owner'?'selected':''}>담당자순</option></select></div><div class="board-summary"><strong>${list.length}개 업무</strong><span>미정 ${data.tasks.filter(t=>t.status==='unassigned').length} · 배정 ${data.tasks.filter(t=>t.status==='assigned').length}</span><button class="text-btn" onclick="clearTaskFilters()">필터 초기화</button></div><div class="panel" style="padding:0;overflow:hidden"><div class="task-grid inner-grid">${list.map(taskCard).join('')||'<div class="empty">조건에 맞는 업무가 없습니다.<br><button class="text-btn" onclick="clearTaskFilters()">필터를 초기화해 보세요</button></div>'}</div></div></section>`}
function recordItem(r){return `<div class="record-item"><div class="record-kind">${r.type==='quant'?'%':'✦'}</div><div class="record-main"><strong>${esc(r.metric)}</strong>${r.type==='qual'?`<p>${esc(r.content)}</p>`:''}<small>${r.date} · ${esc(r.note||'기록')}</small></div>${r.type==='quant'?`<span class="record-number">${r.value}%</span>`:''}</div>`}
function records(){const list=[...data.entries.map(e=>({...e,type:'quant'})),...data.notes.map(n=>({...n,type:'qual'}))].sort((a,b)=>b.id-a.id);return `<section class="view">${heading('KPI 기록','KPI LOG','숫자 실적과 정성 기록을 저장하면 현황판에 반영됩니다.')}<div class="record-layout"><div class="form-card"><h2>기록 입력</h2><p>정량 실적은 숫자만 저장하고, 정성 기록은 글과 사진 주소를 남길 수 있습니다.</p><form id="recordForm"><div class="field"><label>기록 유형</label><select id="recordType"><option value="quant">정량 실적</option><option value="qual">정성 기록</option></select></div><div class="field"><label>지표</label><select id="metric"><option>담당이 정해진 비율</option><option>정성 기록</option></select></div><div class="field" id="valueField"><label>실적 값 (%)</label><input id="value" type="number" min="0" max="100" placeholder="예: 80" /></div><div class="field"><label>기록일</label><input id="date" type="date" value="${today}" required /></div><div class="field"><label id="noteLabel">메모</label><textarea id="note" placeholder="이번 주 변화나 관찰을 적어주세요."></textarea></div><div class="field" id="photoField" style="display:none"><label>사진 주소</label><input id="photoUrl" type="url" placeholder="https://..." /></div><button class="btn" type="submit">기록 저장하기</button></form></div><div><div class="panel-header"><div><div class="panel-title">최근 기록</div><div class="panel-desc">방금 저장한 기록이 목록 맨 위에 표시됩니다.</div></div></div><div class="record-list">${list.map(recordItem).join('')||'<div class="empty">아직 기록이 없습니다.</div>'}</div></div></div></section>`}
function admin(){const assigned=data.tasks.filter(t=>t.status!=='unassigned').length;return `<section class="view">${heading('관리자','CONTROL ROOM','지표 입력 현황, 업무 배정, 변경 이력을 확인하고 관리합니다.','<button class="btn secondary" onclick="downloadCSV()">CSV 다운로드</button>')}<div class="metric-grid"><div class="metric-card"><div class="metric-top"><span>이번 주 입력</span></div><div class="metric-value">${data.entries.length+data.notes.length}<em>건</em></div><div class="metric-note">정량 ${data.entries.length} · 정성 ${data.notes.length}</div></div><div class="metric-card"><div class="metric-top"><span>미배정 업무</span></div><div class="metric-value">${data.tasks.length-assigned}<em>건</em></div><div class="metric-note">담당자와 기한을 확인하세요</div></div><div class="metric-card"><div class="metric-top"><span>담당 변경 이력</span></div><div class="metric-value">${data.history.length}<em>건</em></div><div class="metric-note">변경 내용을 덮어쓰지 않고 보관</div></div></div><div class="panel"><div class="panel-header"><div><div class="panel-title">업무 배정 관리</div><div class="panel-desc">추천 버튼에서 직급·역량·경험·부하율을 반영한 담당 후보를 확인할 수 있습니다.</div></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>항목</th><th>상태</th><th>담당자</th><th>부하율</th><th>기한</th><th>관리</th></tr></thead><tbody>${data.tasks.map(t=>`<tr><td><strong>${esc(t.title)}</strong></td><td><span class="status ${t.status}">${t.status==='assigned'?'배정 완료':'담당 미정'}</span></td><td>${esc(t.owner)}</td><td>${t.owner==='미정'?'—':workload(t.owner)+'%'}</td><td>${t.due}</td><td class="actions"><button class="text-btn" onclick="assignTask(${t.id})">${t.status==='assigned'?'변경':'추천·배정'}</button><button class="text-btn danger" onclick="removeTask(${t.id})">삭제</button></td></tr>`).join('')}</tbody></table></div></div><div class="panel history-panel"><div class="panel-title">최근 담당 변경 이력</div>${data.history.slice(-5).reverse().map(h=>`<p class="history-row"><b>${esc(h.taskTitle)}</b><span>${esc(h.previousOwner||'미정')} → ${esc(h.newOwner)}</span><small>${h.changedAt}</small></p>`).join('')||'<div class="empty">변경 이력이 없습니다.</div>'}</div></section>`}
function team(){return `<section class="view">${heading('팀원 프로필','TEAM DIRECTORY','구성원별 역량·경력·업무부하·담당 영역을 확인합니다.','<button class="btn secondary" onclick="openProfile()">내 프로필</button>')}<div class="team-summary"><div><strong>${data.members.length}</strong><span>전체 구성원</span></div><div><strong>${Math.round(data.members.reduce((a,m)=>a+m.workload,0)/data.members.length)}%</strong><span>평균 업무부하</span></div><div><strong>${data.members.filter(m=>m.workload>=80).length}</strong><span>부하 주의</span></div></div><div class="member-grid">${data.members.map(m=>{const owned=data.tasks.filter(t=>t.owner===m.name);const tone=m.workload>=80?'high':m.workload>=60?'mid':'ok';return `<article class="member-card"><div class="member-top"><span class="profile-avatar small">${esc(m.name[0])}</span><div><h3>${esc(m.name)}</h3><p>${esc(m.level)} · 경력 ${m.experience}년</p></div><span class="member-status ${tone}">${m.workload>=80?'주의':m.workload>=60?'집중':'여유'}</span></div><div class="member-load"><div><span>업무부하</span><strong>${m.workload}%</strong></div><div class="load-bar"><span class="${tone}" style="width:${m.workload}%"></span></div></div><div class="chip-list">${m.skills.map(s=>`<span>${esc(s)}</span>`).join('')}</div><div class="member-footer"><span>담당 업무 <b>${owned.length}건</b></span><button class="text-btn" onclick="openMemberProfile('${esc(m.name)}')">상세 보기 →</button></div></article>`}).join('')}</div></section>`}
function openMemberProfile(name){const m=data.members.find(x=>x.name===name);if(!m)return;const owned=data.tasks.filter(t=>t.owner===name);$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal profile-modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><div class="profile-hero"><span class="profile-avatar">${esc(m.name[0])}</span><div><p class="eyebrow">TEAM MEMBER</p><h2>${esc(m.name)}</h2><p>${esc(m.level)} · ${m.experience}년 경력</p></div></div><div class="profile-grid"><div class="profile-block"><label>핵심 역량</label><div class="chip-list">${m.skills.map(s=>`<span>${esc(s)}</span>`).join('')}</div></div><div class="profile-block"><label>현재 업무부하</label><div class="profile-load"><strong>${m.workload}%</strong><div class="load-bar"><span class="${m.workload>=80?'high':m.workload>=60?'mid':'ok'}" style="width:${m.workload}%"></span></div></div></div></div><div class="member-task-list"><label>담당 업무</label>${owned.map(t=>`<button onclick="openTaskDetail(${t.id})"><span class="status ${t.status}">${statusLabel(t.status)}</span><b>${esc(t.title)}</b><small>${t.due||'기한 미지정'}</small></button>`).join('')||'<div class="empty">담당 업무 없음</div>'}</div></section></div>`}
function render(){syncComputedWorkloads();const views={dashboard,tasks,team,records,admin};let html=views[current]();if(current==='dashboard')html=html.replace('</section>',dashboardExtras()+'</section>');if(current==='admin')html=html.replace('</section>',adminExtras()+'</section>');$('#app').innerHTML=html;$('#pageTitle').textContent={dashboard:'현황판',tasks:'업무 항목',team:'팀원 프로필',records:'KPI 기록',admin:'관리자'}[current];document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===current));$('#navTaskCount').textContent=data.tasks.filter(t=>['assigned','in_progress','blocked'].includes(t.status)).length;bindForms();bindTaskFilters();bindShellActions()}
function go(v){current=v;render();window.scrollTo({top:0,behavior:'smooth'})}
function bindTaskFilters(){const q=$('#taskSearch');if(!q)return;q.onkeydown=e=>{if(e.key==='Enter'){taskQuery=q.value;render()}};$('#taskStatusFilter').onchange=e=>{taskStatus=e.target.value;render()};$('#taskOwnerFilter').onchange=e=>{taskOwner=e.target.value;render()};$('#taskSort').onchange=e=>{taskSort=e.target.value;render()}}
function clearTaskFilters(){taskQuery='';taskStatus='all';taskOwner='all';taskSort='due';render()}
function bindForms(){const form=$('#recordForm');if(!form)return;$('#recordType').onchange=()=>{const q=$('#recordType').value==='quant';$('#valueField').style.display=q?'block':'none';$('#photoField').style.display=q?'none':'block';$('#noteLabel').textContent=q?'메모':'기록 내용'};form.onsubmit=async e=>{e.preventDefault();const type=$('#recordType').value,date=$('#date').value;if(type==='quant'){const value=Number($('#value').value);if(!Number.isFinite(value))return toast('숫자 값을 입력해주세요.');const entry={id:Date.now(),metric:$('#metric').value,value,date,note:$('#note').value||'기록'};data.entries.unshift(entry);await cloudRequest('kpi_entry','POST',{metric_id:1,value:entry.value,recorded_on:entry.date,note:entry.note})}else{const note={id:Date.now(),metric:'정성 기록',content:$('#note').value,photoUrl:$('#photoUrl').value||'',date};data.notes.unshift(note);await cloudRequest('kpi_note','POST',{metric_id:2,content:note.content,photo_url:note.photoUrl,recorded_on:note.date})}save();toast('기록이 저장되었습니다.');render()}}
function openTaskForm(){const title=prompt('업무명을 입력해주세요.');if(!title)return;const desc=prompt('업무 설명을 입력해주세요.','새로 등록한 업무 항목')||'';const level=prompt('필요 직급을 입력해주세요.','선임')||'선임';const skills=(prompt('필요 역량을 쉼표로 입력해주세요.','교육기획')||'').split(',').map(x=>x.trim()).filter(Boolean);const experience=Number(prompt('최소 관련 경험(년)을 입력해주세요.','3'))||0;const hours=Number(prompt('예상 소요 시간(시간)을 입력해주세요.','8'))||8;const collaborators=(prompt('협업 부서를 쉼표로 입력해주세요.','')||'').split(',').map(x=>x.trim()).filter(Boolean);data.tasks.push({id:Date.now(),title,description:desc,owner:'미정',due:today,status:'unassigned',createdBy:'김민정',createdAt:today,requiredLevel:level,requiredSkills:skills,minExperience:experience,estimatedHours:hours,collaborators});save();toast('새 업무가 등록되었습니다.');render()}
function recommend(t){return data.members.map(m=>{let score=0;if(m.level===t.requiredLevel)score+=30;if((t.requiredSkills||[]).some(s=>m.skills.includes(s)))score+=30;if(m.experience>=(t.minExperience||0))score+=20;score+=Math.max(0,20-(m.workload/5));return {...m,score:Math.round(score)}}).sort((a,b)=>b.score-a.score)}
function assignTask(id){const t=data.tasks.find(x=>x.id===id);const candidates=recommend(t);const message=`추천 후보\n${candidates.slice(0,3).map((m,i)=>`${i+1}. ${m.name} · 적합도 ${m.score}점 · 현재 부하 ${m.workload}% · ${m.skills.join(', ')}`).join('\n')}\n\n담당자 이름을 입력하세요.`;const owner=prompt(message,t.owner==='미정'?candidates[0]?.name:t.owner);if(!owner||!data.members.some(m=>m.name===owner))return owner?toast('등록된 구성원 이름을 입력해주세요.'):null;const old=t.owner;t.owner=owner;t.status='assigned';data.history.push({id:Date.now(),taskId:t.id,taskTitle:t.title,previousOwner:old,newOwner:owner,changedAt:today});save();toast(`${owner}님에게 배정했습니다.`);render()}
function openSatisfaction(id){const t=data.tasks.find(x=>x.id===id);const fit=prompt('나에게 적절한 수준의 업무였나요? (적절 / 쉬움 / 어려움)','적절');if(!fit)return;const load=prompt('업무 부하는 어땠나요? (적정 / 과다 / 여유)','적정')||'적정';const challenge=prompt('더 난이도 있는 업무도 괜찮나요? (예 / 아니오)','예')||'예';const comment=prompt('추가 의견을 남겨주세요.','')||'';data.satisfaction.push({id:Date.now(),taskId:id,taskTitle:t.title,owner:t.owner,fit,load,challenge,comment,date:today});save();toast('업무 만족도가 저장되었습니다.');render()}
function removeTask(id){if(!confirm('이 업무 항목을 삭제할까요?'))return;data.tasks=data.tasks.filter(t=>t.id!==id);save();toast('업무 항목을 삭제했습니다.');render()}
function downloadCSV(){const rows=[['지표 이름','값 또는 기록 내용','날짜','메모'],...data.entries.map(e=>[e.metric,e.value,e.date,e.note||'']),...data.notes.map(n=>[n.metric,n.content,n.date,n.photoUrl||''])];const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='rr-kpi-records.csv';a.click();toast('CSV 다운로드를 시작했습니다.')}

// Complete interaction layer: profile, modal task creation, one-click auto assignment.
function bestCandidate(t){return recommend(t).find(m=>m.workload<85)||recommend(t)[0]}
function autoAssignTask(id){const t=data.tasks.find(x=>x.id===id);if(!t)return;const candidate=bestCandidate(t);if(!candidate)return toast('추천 가능한 구성원이 없습니다.');const old=t.owner;t.owner=candidate.name;t.status='assigned';const member=data.members.find(m=>m.name===candidate.name);if(member)member.workload=Math.min(100,Math.round(member.workload+(t.estimatedHours||8)/40*100));data.history.push({id:Date.now(),taskId:t.id,taskTitle:t.title,previousOwner:old,newOwner:candidate.name,changedAt:today,method:'auto'});save();toast(`${candidate.name}님에게 자동 배정했습니다.`);render()}
function closeModal(){const root=$('#modalRoot');if(root)root.innerHTML=''}
function openProfile(){const member=data.members[0];const owned=data.tasks.filter(t=>t.owner===member.name);const sat=data.satisfaction.filter(s=>s.owner===member.name);$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal profile-modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><div class="profile-hero"><span class="profile-avatar">${esc(member.name[0])}</span><div><p class="eyebrow">MY PROFILE</p><h2>${esc(member.name)}</h2><p>${esc(member.level)} · ${member.experience}년 경력</p></div></div><div class="profile-grid"><div class="profile-block"><label>핵심 역량</label><div class="chip-list">${member.skills.map(s=>`<span>${esc(s)}</span>`).join('')}</div></div><div class="profile-block"><label>현재 업무부하</label><div class="profile-load"><strong>${member.workload}%</strong><div class="load-bar"><span class="${member.workload>=80?'high':member.workload>=60?'mid':'ok'}" style="width:${member.workload}%"></span></div></div></div><div class="profile-block"><label>담당 업무</label><strong>${owned.length}건</strong><small>${owned.map(t=>esc(t.title)).join(' · ')||'현재 담당 업무 없음'}</small></div><div class="profile-block"><label>업무 만족도 응답</label><strong>${sat.length}건</strong><small>${sat.length?'최근 응답 '+sat[sat.length-1].date:'아직 응답 없음'}</small></div></div><button class="btn secondary full" onclick="go('tasks');closeModal()">내 업무만 보기</button></section></div>`}
function openTaskForm(){const root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal task-modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><p class="eyebrow">NEW WORK ITEM</p><h2>새 업무 등록</h2><p class="modal-help">업무 조건을 입력하면 자동 배정 시 적합도와 업무부하를 함께 계산합니다.</p><form id="taskModalForm" class="modal-form"><div class="form-grid"><div class="field full-field"><label>업무명 <em>*</em></label><input name="title" required placeholder="예: 노사협의체 운영"></div><div class="field full-field"><label>업무 설명</label><textarea name="description" placeholder="업무 목적, 주요 산출물을 적어주세요."></textarea></div><div class="field"><label>필요 직급</label><select name="level"><option>사원</option><option>선임</option><option>책임</option><option>팀장</option></select></div><div class="field"><label>최소 경험(년)</label><input name="experience" type="number" min="0" value="3"></div><div class="field"><label>필요 역량</label><input name="skills" placeholder="쉼표로 구분"></div><div class="field"><label>예상 시간(시간)</label><input name="hours" type="number" min="1" value="8"></div><div class="field"><label>기한</label><input name="due" type="date" value="${today}" required></div><div class="field"><label>협업 부서</label><input name="collaborators" placeholder="쉼표로 구분"></div></div><div class="modal-actions"><button type="button" class="btn secondary" onclick="closeModal()">취소</button><button class="btn" type="submit">업무 등록</button></div></form></section></div>`;$('#taskModalForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const title=String(f.get('title')).trim();if(!title)return;data.tasks.push({id:Date.now(),title,description:String(f.get('description')||''),owner:'미정',due:String(f.get('due')),status:'unassigned',createdBy:data.members[0].name,createdAt:today,requiredLevel:String(f.get('level')),requiredSkills:String(f.get('skills')||'').split(',').map(x=>x.trim()).filter(Boolean),minExperience:Number(f.get('experience'))||0,estimatedHours:Number(f.get('hours'))||8,collaborators:String(f.get('collaborators')||'').split(',').map(x=>x.trim()).filter(Boolean)});save();closeModal();toast('새 업무가 등록되었습니다.');render()}}
function taskCard(t){const due=t.due?.slice(5).replace('-','.');const candidate=t.status==='unassigned'?bestCandidate(t):null;return `<article class="task-tile ${t.status}"><div class="task-head"><span class="status ${t.status}">${t.status==='assigned'?'배정 완료':'담당 미정'}</span><span class="priority">${t.estimatedHours||0}h</span></div><h3>${esc(t.title)}</h3><p class="task-meta">${esc(t.description)}</p><div class="task-tags">${(t.collaborators||[]).map(c=>`<span>협업 · ${esc(c)}</span>`).join('')||'<span>협업 부서 미지정</span>'}</div><div class="task-footer"><span class="owner-chip"><span class="mini-avatar">${t.owner==='미정'?'?':esc(t.owner[0])}</span>${esc(t.owner)}${t.owner!=='미정'?`<small>부하 ${workload(t.owner)}%</small>`:''}</span><span class="date">마감 ${due}</span></div>${t.status==='unassigned'?`<div class="recommend-box"><span>추천 후보 <b>${candidate?esc(candidate.name):'없음'}</b><small>${candidate?`적합도 ${candidate.score}점 · 부하 ${candidate.workload}%`:''}</small></span><button class="auto-assign-btn" onclick="autoAssignTask(${t.id})">자동 배정</button></div>`:`<button class="satisfaction-btn" onclick="openSatisfaction(${t.id})">업무 만족도 남기기</button>`}</article>`}
function bindShellActions(){const profile=$('#profileBtn');if(profile)profile.onclick=openProfile}
function statusLabel(status){return {unassigned:'담당 미정',assigned:'배정 완료',in_progress:'진행 중',blocked:'막힘',done:'완료'}[status]||status}
function changeTaskStatus(id,status){const t=data.tasks.find(x=>x.id===id);if(!t)return;const old=t.status;t.status=status;data.history.push({id:Date.now(),taskId:id,taskTitle:t.title,previousOwner:statusLabel(old),newOwner:statusLabel(status),changedAt:today,method:'status'});save();closeModal();toast(`${statusLabel(status)} 상태로 변경했습니다.`);render()}
function openTaskDetail(id){const t=data.tasks.find(x=>x.id===id);if(!t)return;const candidates=recommend(t).slice(0,3);$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal detail-modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><div class="detail-top"><div><span class="status ${t.status}">${statusLabel(t.status)}</span><p class="eyebrow">WORK ITEM DETAIL</p><h2>${esc(t.title)}</h2><p class="modal-help">${esc(t.description||'설명 없음')}</p></div><div class="detail-hours"><strong>${t.estimatedHours||0}h</strong><small>예상 소요</small></div></div><div class="detail-grid"><div><label>담당자</label><strong>${esc(t.owner)}</strong>${t.owner!=='미정'?`<small>현재 부하 ${workload(t.owner)}%</small>`:'<small>자동 배정 또는 수동 배정 필요</small>'}</div><div><label>기한</label><strong>${t.due||'미지정'}</strong><small>${t.due&&t.due<today?'기한 초과':'기한 내'}</small></div><div><label>필요 조건</label><strong>${esc(t.requiredLevel||'미지정')}</strong><small>${(t.requiredSkills||[]).join(' · ')||'역량 미지정'} · ${t.minExperience||0}년 이상</small></div><div><label>협업 부서</label><strong>${(t.collaborators||[]).map(esc).join(' · ')||'미지정'}</strong><small>업무 등록 시 지정한 협업 대상</small></div></div><div class="detail-section"><label>상태 변경</label><div class="status-actions">${['unassigned','assigned','in_progress','blocked','done'].map(s=>`<button class="status-choice ${s===t.status?'selected':''}" onclick="changeTaskStatus(${id},'${s}')">${statusLabel(s)}</button>`).join('')}</div></div><div class="detail-section"><div class="detail-section-head"><label>추천 후보</label><small>직급·역량·경험·부하 종합</small></div><div class="candidate-list">${candidates.map((m,i)=>`<div class="candidate-row"><span class="candidate-rank">${i+1}</span><div><strong>${esc(m.name)}</strong><small>${esc(m.level)} · ${m.skills.join(' · ')}</small></div><b>${m.score}점</b><em>부하 ${m.workload}%</em></div>`).join('')||'<div class="empty">추천 후보 없음</div>'}</div></div><div class="modal-actions"><button class="btn secondary" onclick="closeModal()">닫기</button>${t.status==='unassigned'?`<button class="btn" onclick="autoAssignTask(${id})">자동 배정</button>`:`<button class="btn secondary" onclick="openSatisfaction(${id});closeModal()">만족도 기록</button>`}</div></section></div>`}
function taskCard(t){const due=t.due?.slice(5).replace('-','.');const candidate=t.status==='unassigned'?bestCandidate(t):null;return `<article class="task-tile ${t.status}"><div class="task-head"><button class="status ${t.status}" onclick="openTaskDetail(${t.id})">${statusLabel(t.status)}</button><span class="priority">${t.estimatedHours||0}h</span></div><button class="task-title-button" onclick="openTaskDetail(${t.id})"><h3>${esc(t.title)}</h3></button><p class="task-meta">${esc(t.description)}</p><div class="task-tags">${(t.collaborators||[]).map(c=>`<span>협업 · ${esc(c)}</span>`).join('')||'<span>협업 부서 미지정</span>'}</div><div class="task-footer"><span class="owner-chip"><span class="mini-avatar">${t.owner==='미정'?'?':esc(t.owner[0])}</span>${esc(t.owner)}${t.owner!=='미정'?`<small>부하 ${workload(t.owner)}%</small>`:''}</span><span class="date">마감 ${due}</span></div>${t.status==='unassigned'?`<div class="recommend-box"><span>추천 후보 <b>${candidate?esc(candidate.name):'없음'}</b><small>${candidate?`적합도 ${candidate.score}점 · 부하 ${candidate.workload}%`:''}</small></span><button class="auto-assign-btn" onclick="autoAssignTask(${t.id})">자동 배정</button></div>`:`<button class="satisfaction-btn" onclick="openSatisfaction(${t.id})">업무 만족도 남기기</button>`}</article>`}
function tasks(){const list=filteredTasks();return `<section class="view">${heading('업무 항목','R&R BOARD','업무 상태·담당자·기한을 한 화면에서 관리합니다.','<button class="btn" onclick="openTaskForm()">+ 새 업무 올리기</button>')}<div class="board-toolbar"><div class="search-box"><span>⌕</span><input id="taskSearch" value="${esc(taskQuery)}" placeholder="업무명, 설명, 협업 부서 검색" aria-label="업무 검색"></div><select id="taskStatusFilter" aria-label="상태 필터"><option value="all" ${taskStatus==='all'?'selected':''}>모든 상태</option>${['unassigned','assigned','in_progress','blocked','done'].map(s=>`<option value="${s}" ${taskStatus===s?'selected':''}>${statusLabel(s)}</option>`).join('')}</select><select id="taskOwnerFilter" aria-label="담당자 필터"><option value="all">모든 담당자</option>${data.members.map(m=>`<option value="${esc(m.name)}" ${taskOwner===m.name?'selected':''}>${esc(m.name)}</option>`).join('')}</select><select id="taskSort" aria-label="정렬"><option value="due" ${taskSort==='due'?'selected':''}>마감 임박순</option><option value="new" ${taskSort==='new'?'selected':''}>최근 등록순</option><option value="owner" ${taskSort==='owner'?'selected':''}>담당자순</option></select></div><div class="board-summary"><strong>${list.length}개 업무</strong><span>미정 ${data.tasks.filter(t=>t.status==='unassigned').length} · 진행 ${data.tasks.filter(t=>t.status==='in_progress').length} · 완료 ${data.tasks.filter(t=>t.status==='done').length}</span><button class="text-btn" onclick="clearTaskFilters()">필터 초기화</button></div><div class="panel" style="padding:0;overflow:hidden"><div class="task-grid inner-grid">${list.map(taskCard).join('')||'<div class="empty">조건에 맞는 업무가 없습니다.</div>'}</div></div></section>`}
const TASK_TYPES=['교육 운영','노사·협의체','진단·평가','조직문화','기획·프로젝트','고객·문의 대응'];
const TASK_LEVELS=GRADE_LEVELS;
const SKILL_LIBRARY=['교육기획','교육운영','입문교육','노사관계','진단운영','리더십','조직문화','콘텐츠','협업','고객대응','데이터분석','프로젝트관리'];
const TASK_TYPE_PRESETS={
  '교육 운영':{difficulty:'중',level:'G1D',experience:2,hours:8,skills:['교육운영','교육기획']},
  '노사·협의체':{difficulty:'상',level:'G2',experience:4,hours:12,skills:['노사관계','협업']},
  '진단·평가':{difficulty:'상',level:'G2',experience:4,hours:12,skills:['진단운영']},
  '조직문화':{difficulty:'중',level:'G1D',experience:3,hours:10,skills:['조직문화','교육기획']},
  '기획·프로젝트':{difficulty:'상',level:'G2',experience:4,hours:16,skills:['교육기획','협업']},
  '고객·문의 대응':{difficulty:'하',level:'G1S',experience:1,hours:4,skills:['협업']}
};
function applyTaskTypePreset(form,type){const preset=TASK_TYPE_PRESETS[type];if(!preset)return;if(form.elements.difficulty)form.elements.difficulty.value=preset.difficulty;if(form.elements.level)form.elements.level.value=preset.level;if(form.elements.experience)form.elements.experience.value=preset.experience;if(form.elements.hours)form.elements.hours.value=preset.hours;form.querySelectorAll('input[name="skills"]').forEach(input=>{input.checked=preset.skills.includes(input.value)})}
function bindTaskTypePreset(form){if(!form||form.dataset.typePresetBound)return;form.dataset.typePresetBound='true';const typeField=form.elements.taskType;if(!typeField)return;typeField.addEventListener('change',()=>applyTaskTypePreset(form,typeField.value));applyTaskTypePreset(form,typeField.value)}
new MutationObserver(()=>document.querySelectorAll('#taskModalForm,#roleTaskForm').forEach(bindTaskTypePreset)).observe(document.body,{childList:true,subtree:true});
function levelRank(v){return TASK_LEVELS.indexOf(v)<0?0:TASK_LEVELS.indexOf(v)}
function recommend(t){const required=(t.requiredSkills||[]).filter(Boolean);return data.members.map(m=>{const typeMatch=(m.types||[]).includes(t.taskType)?30:0;const skillHits=required.filter(s=>(m.skills||[]).includes(s)).length;const skillScore=required.length?Math.round(skillHits/required.length*30):15;const levelScore=levelRank(m.level)>=levelRank(t.requiredLevel||t.difficulty)?20:5;const expScore=m.experience>=(t.minExperience||0)?10:Math.max(0,10-Math.round(((t.minExperience||0)-m.experience)*2));const capacityScore=Math.max(0,10-Math.round(m.workload/10));const score=Math.max(0,Math.round(typeMatch+skillScore+levelScore+expScore+capacityScore));const eligible=m.workload<(m.maxWorkload||85)&&levelRank(m.level)>=Math.max(0,levelRank(t.requiredLevel||'사원')-1);return {...m,score,eligible,breakdown:{type:typeMatch,skills:skillScore,level:levelScore,experience:expScore,capacity:capacityScore},skillHits}}).sort((a,b)=>(Number(b.eligible)-Number(a.eligible))||b.score-a.score)}
function bestCandidate(t){return recommend(t).find(m=>m.eligible)||recommend(t)[0]}
function openMemberEditor(name){const m=data.members.find(x=>x.name===name);if(!m)return;const d=GRADE_DEFAULTS[m.level]||GRADE_DEFAULTS['사원'];$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><p class="eyebrow">CAPABILITY SETTINGS</p><h2>${esc(m.name)} 업무부하 설정</h2><p class="modal-help">현재 부하율은 배정된 업무에서 자동 계산됩니다. 여기서는 개인별 업무 가능량만 설정합니다.</p><div class="computed-load-callout"><span>현재 자동 계산 부하</span><strong>${calculatedWorkload(m)}%</strong><small>배정 업무 예상시간 · 난이도 · 역량 적합도 반영</small></div><form id="memberForm" class="modal-form"><div class="form-grid"><div class="field"><label>직급</label><select name="level" id="memberLevel">${TASK_LEVELS.map(x=>`<option ${m.level===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>경력(년)</label><input name="experience" type="number" min="0" value="${m.experience||d.experience}"></div><div class="field"><label>주당 업무 가능시간</label><input name="capacityHours" type="number" min="1" max="60" value="${m.capacityHours||d.capacityHours}"><small class="field-help">이 구성원이 R&R 업무에 쓸 수 있는 주당 시간</small></div><div class="field"><label>이번 기간 가용 비율(%)</label><input name="availability" type="number" min="25" max="100" value="${Math.round((m.availability||1)*100)}"><small class="field-help">휴직·교육·겸임 등 반영</small></div><div class="field"><label>배정 허용 상한(%)</label><input name="maxWorkload" type="number" min="50" max="150" value="${m.maxWorkload||d.maxWorkload}"></div><div class="field full-field grade-default-row"><span class="grade-default-hint">직급 기본값: 주당 ${d.capacityHours}시간 · 가용 ${Math.round(d.availability*100)}%</span><button type="button" class="text-btn" id="resetGradeDefaults">직급 기본값 적용</button></div><div class="field full-field"><label>수행 가능 업무 종류</label><div class="check-grid">${TASK_TYPES.map(x=>`<label class="check-chip"><input type="checkbox" name="types" value="${x}" ${(m.types||d.types).includes(x)?'checked':''}><span>${x}</span></label>`).join('')}</div></div><div class="field full-field"><label>보유 역량</label><div class="check-grid">${SKILL_LIBRARY.map(x=>`<label class="check-chip"><input type="checkbox" name="skills" value="${x}" ${(m.skills||d.skills).includes(x)?'checked':''}><span>${x}</span></label>`).join('')}</div></div></div><div class="modal-actions"><button type="button" class="btn secondary" onclick="closeModal()">취소</button><button class="btn" type="submit">설정 저장</button></div></form></section></div>`;const form=$('#memberForm');$('#memberLevel').onchange=e=>{const next=GRADE_DEFAULTS[e.target.value];form.elements.experience.value=next.experience;form.elements.capacityHours.value=next.capacityHours;form.elements.availability.value=Math.round(next.availability*100);form.elements.maxWorkload.value=next.maxWorkload;applyGradeDefaults(form,e.target.value,false);form.querySelector('.grade-default-hint').textContent=`${e.target.value} 기본값: 주당 ${next.capacityHours}시간 · 가용 ${Math.round(next.availability*100)}%`};$('#resetGradeDefaults').onclick=()=>$('#memberLevel').dispatchEvent(new Event('change'));form.onsubmit=e=>{e.preventDefault();const f=new FormData(form);m.level=String(f.get('level'));m.experience=Number(f.get('experience'))||0;m.capacityHours=Number(f.get('capacityHours'))||d.capacityHours;m.availability=Math.max(.25,Math.min(1,Number(f.get('availability'))/100||1));m.maxWorkload=Math.max(50,Math.min(150,Number(f.get('maxWorkload'))||d.maxWorkload));m.types=f.getAll('types');m.skills=f.getAll('skills');m.capabilities=m.skills;m.profileSource='individual';syncComputedWorkloads();save();closeModal();toast('개인별 업무 가능량을 저장했습니다.');render()}}
function autoAssignTask(id){const t=data.tasks.find(x=>x.id===id);if(!t)return;const candidate=bestCandidate(t);if(!candidate)return toast('추천 가능한 구성원이 없습니다.');const old=t.owner;t.owner=candidate.name;t.status='assigned';const created=new Date(t.createdAt||today);const assigned=new Date(today);t.assignedAt=today;t.assignmentHours=Math.max(0,Math.round(((assigned-created)/86400000||0.5)*10)/10);data.history.push({id:Date.now(),taskId:t.id,taskTitle:t.title,previousOwner:old,newOwner:candidate.name,changedAt:today,method:'auto',score:candidate.score});syncComputedWorkloads();save();toast(`${candidate.name}님에게 자동 배정했습니다.`);render()}
function openMemberEditor(name){const m=data.members.find(x=>x.name===name);if(!m)return;$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><p class="eyebrow">CAPABILITY SETTINGS</p><h2>${esc(m.name)} 역량 설정</h2><p class="modal-help">자동 배정은 아래 정보와 현재 업무부하를 함께 계산합니다.</p><form id="memberForm" class="modal-form"><div class="form-grid"><div class="field"><label>직급</label><select name="level">${TASK_LEVELS.map(x=>`<option ${m.level===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>경력(년)</label><input name="experience" type="number" min="0" value="${m.experience}"></div><div class="field full-field"><label>수행 가능 업무 종류</label><div class="check-grid">${TASK_TYPES.map(x=>`<label class="check-chip"><input type="checkbox" name="types" value="${x}" ${(m.types||[]).includes(x)?'checked':''}><span>${x}</span></label>`).join('')}</div></div><div class="field full-field"><label>보유 역량</label><div class="check-grid">${SKILL_LIBRARY.map(x=>`<label class="check-chip"><input type="checkbox" name="skills" value="${x}" ${(m.skills||[]).includes(x)?'checked':''}><span>${x}</span></label>`).join('')}</div></div><div class="field"><label>현재 업무부하(%)</label><input name="workload" type="number" min="0" max="100" value="${m.workload}"></div><div class="field"><label>배정 허용 상한(%)</label><input name="maxWorkload" type="number" min="0" max="100" value="${m.maxWorkload||85}"></div></div><div class="modal-actions"><button type="button" class="btn secondary" onclick="closeModal()">취소</button><button class="btn" type="submit">역량 저장</button></div></form></section></div>`;$('#memberForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);m.level=String(f.get('level'));m.experience=Number(f.get('experience'))||0;m.types=f.getAll('types');m.skills=f.getAll('skills');m.capabilities=m.skills;m.workload=Math.max(0,Math.min(100,Number(f.get('workload'))||0));m.maxWorkload=Math.max(0,Math.min(100,Number(f.get('maxWorkload'))||85));save();closeModal();toast('역량 정보를 저장했습니다.');render()}}
function openTaskForm(){const root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal task-modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><p class="eyebrow">NEW WORK ITEM</p><h2>자동 배정 업무 등록</h2><p class="modal-help">업무 종류·난이도·필요 역량을 구체적으로 입력할수록 추천 정확도가 높아집니다.</p><form id="taskModalForm" class="modal-form"><div class="form-grid"><div class="field full-field"><label>업무명 <em>*</em></label><input name="title" required placeholder="예: 리더십다면진단 운영"></div><div class="field full-field"><label>업무 설명</label><textarea name="description" placeholder="업무 목적과 주요 결과물을 적어주세요."></textarea></div><div class="field"><label>업무 종류</label><select name="taskType">${TASK_TYPES.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>업무 난이도</label><select name="difficulty">${TASK_LEVELS.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>필요 최소 직급</label><select name="level">${TASK_LEVELS.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>최소 경험(년)</label><input name="experience" type="number" min="0" value="3"></div><div class="field full-field"><label>필요 역량</label><div class="check-grid">${SKILL_LIBRARY.map(x=>`<label class="check-chip"><input type="checkbox" name="skills" value="${x}"><span>${x}</span></label>`).join('')}</div></div><div class="field"><label>예상 소요시간</label><input name="hours" type="number" min="1" value="8"></div><div class="field"><label>기한</label><input name="due" type="date" value="${today}" required></div><div class="field full-field"><label>협업 부서</label><input name="collaborators" placeholder="쉼표로 구분"></div></div><div class="modal-actions"><button type="button" class="btn secondary" onclick="closeModal()">취소</button><button class="btn" type="submit">업무 등록</button></div></form></section></div>`;$('#taskModalForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const title=String(f.get('title')).trim();if(!title)return;data.tasks.push({id:Date.now(),title,description:String(f.get('description')||''),owner:'미정',due:String(f.get('due')),status:'unassigned',createdBy:data.members[0].name,createdAt:today,taskType:String(f.get('taskType')),difficulty:String(f.get('difficulty')),requiredLevel:String(f.get('level')),requiredSkills:f.getAll('skills'),minExperience:Number(f.get('experience'))||0,estimatedHours:Number(f.get('hours'))||8,collaborators:String(f.get('collaborators')||'').split(',').map(x=>x.trim()).filter(Boolean)});save();closeModal();toast('자동 배정 대기 업무를 등록했습니다.');render()}}
function team(){return `<section class="view">${heading('팀원 프로필','TEAM DIRECTORY','구성원별 역량·업무 종류·경력·부하를 설정합니다.','<button class="btn secondary" onclick="openProfile()">내 프로필</button>')}<div class="team-summary"><div><strong>${data.members.length}</strong><span>전체 구성원</span></div><div><strong>${Math.round(data.members.reduce((a,m)=>a+m.workload,0)/data.members.length)}%</strong><span>평균 업무부하</span></div><div><strong>${data.members.filter(m=>m.skills.length&&m.types.length).length}/${data.members.length}</strong><span>역량 설정 완료</span></div></div><div class="member-grid">${data.members.map(m=>{const owned=data.tasks.filter(t=>t.owner===m.name);const tone=m.workload>=80?'high':m.workload>=60?'mid':'ok';return `<article class="member-card"><div class="member-top"><span class="profile-avatar small">${esc(m.name[0])}</span><div><h3>${esc(m.name)}</h3><p>${esc(m.level)} · 경력 ${m.experience}년</p></div><span class="member-status ${tone}">${m.workload>=80?'주의':m.workload>=60?'집중':'여유'}</span></div><div class="member-load"><div><span>업무부하</span><strong>${m.workload}%</strong></div><div class="load-bar"><span class="${tone}" style="width:${m.workload}%"></span></div></div><div class="member-capability"><label>가능 업무</label><span>${(m.types||[]).join(' · ')||'미설정'}</span></div><div class="chip-list">${m.skills.map(s=>`<span>${esc(s)}</span>`).join('')||'<span>역량 미설정</span>'}</div><div class="member-footer"><span>담당 업무 <b>${owned.length}건</b></span><button class="text-btn" onclick="openMemberEditor('${esc(m.name)}')">역량 설정</button></div></article>`}).join('')}</div></section>`}
function taskCard(t){const due=t.due?.slice(5).replace('-','.');const candidate=t.status==='unassigned'?bestCandidate(t):null;return `<article class="task-tile ${t.status}"><div class="task-head"><button class="status ${t.status}" onclick="openTaskDetail(${t.id})">${statusLabel(t.status)}</button><span class="priority">${esc(t.taskType||'업무')} · ${esc(t.difficulty||'')} · ${t.estimatedHours||0}h</span></div><button class="task-title-button" onclick="openTaskDetail(${t.id})"><h3>${esc(t.title)}</h3></button><p class="task-meta">${esc(t.description)}</p><div class="task-tags">${(t.requiredSkills||[]).map(s=>`<span>역량 · ${esc(s)}</span>`).join('')}${(t.collaborators||[]).map(c=>`<span>협업 · ${esc(c)}</span>`).join('')}</div><div class="task-footer"><span class="owner-chip"><span class="mini-avatar">${t.owner==='미정'?'?':esc(t.owner[0])}</span>${esc(t.owner)}${t.owner!=='미정'?`<small>부하 ${workload(t.owner)}%</small>`:''}</span><span class="date">마감 ${due}</span></div>${t.status==='unassigned'?`<div class="recommend-box"><span>추천 후보 <b>${candidate?esc(candidate.name):'없음'}</b><small>${candidate?`적합도 ${candidate.score}점 · ${candidate.eligible?'배정 가능':'상한 초과'} · 부하 ${candidate.workload}%`:''}</small></span><button class="auto-assign-btn" onclick="autoAssignTask(${t.id})">자동 배정</button></div>`:`<button class="satisfaction-btn" onclick="openSatisfaction(${t.id})">업무 만족도 남기기</button>`}</article>`}
function applyGradeDefaults(form,level,overwrite=true){const d=GRADE_DEFAULTS[level];if(!d)return;form.querySelectorAll('input[name="types"]').forEach(x=>x.checked=d.types.includes(x.value));form.querySelectorAll('input[name="skills"]').forEach(x=>x.checked=d.skills.includes(x.value));if(overwrite){if(form.elements.experience)form.elements.experience.value=d.experience;if(form.elements.maxWorkload)form.elements.maxWorkload.value=d.maxWorkload}const hint=form.querySelector('.grade-default-hint');if(hint)hint.textContent=`${level} 기본값 적용 · 업무 종류 ${d.types.length}개 · 역량 ${d.skills.length}개`}
function openMemberEditor(name){const m=data.members.find(x=>x.name===name);if(!m)return;const d=GRADE_DEFAULTS[m.level]||GRADE_DEFAULTS['사원'];$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><p class="eyebrow">CAPABILITY SETTINGS</p><h2>${esc(m.name)} 역량 설정</h2><p class="modal-help">직급 변경 시 기본값이 자동 적용됩니다. 이후 체크 항목은 개인별 설정으로 저장됩니다.</p><form id="memberForm" class="modal-form"><div class="form-grid"><div class="field"><label>직급</label><select name="level" id="memberLevel">${TASK_LEVELS.map(x=>`<option ${m.level===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>경력(년)</label><input name="experience" type="number" min="0" value="${m.experience||d.experience}"></div><div class="field full-field grade-default-row"><span class="grade-default-hint">${m.profileSource==='individual'?'개인별 설정 적용 중':`${m.level} 기본값 적용 · 업무 종류 ${(m.types||d.types).length}개 · 역량 ${(m.skills||d.skills).length}개`}</span><button type="button" class="text-btn" id="resetGradeDefaults">직급 기본값으로 재설정</button></div><div class="field full-field"><label>수행 가능 업무 종류</label><div class="check-grid">${TASK_TYPES.map(x=>`<label class="check-chip"><input type="checkbox" name="types" value="${x}" ${(m.types||d.types).includes(x)?'checked':''}><span>${x}</span></label>`).join('')}</div></div><div class="field full-field"><label>보유 역량</label><div class="check-grid">${SKILL_LIBRARY.map(x=>`<label class="check-chip"><input type="checkbox" name="skills" value="${x}" ${(m.skills||d.skills).includes(x)?'checked':''}><span>${x}</span></label>`).join('')}</div></div><div class="field"><label>현재 업무부하(%)</label><input name="workload" type="number" min="0" max="100" value="${m.workload}"></div><div class="field"><label>배정 허용 상한(%)</label><input name="maxWorkload" type="number" min="0" max="100" value="${m.maxWorkload||d.maxWorkload}"></div></div><div class="modal-actions"><button type="button" class="btn secondary" onclick="closeModal()">취소</button><button class="btn" type="submit">개인 역량 저장</button></div></form></section></div>`;const form=$('#memberForm');$('#memberLevel').onchange=e=>applyGradeDefaults(form,e.target.value,true);$('#resetGradeDefaults').onclick=()=>applyGradeDefaults(form,$('#memberLevel').value,true);form.onsubmit=e=>{e.preventDefault();const f=new FormData(form);m.level=String(f.get('level'));m.experience=Number(f.get('experience'))||0;m.types=f.getAll('types');m.skills=f.getAll('skills');m.capabilities=m.skills;m.workload=Math.max(0,Math.min(100,Number(f.get('workload'))||0));m.maxWorkload=Math.max(0,Math.min(100,Number(f.get('maxWorkload'))||GRADE_DEFAULTS[m.level].maxWorkload));m.profileSource='individual';save();closeModal();toast('개인별 역량 설정을 저장했습니다.');render()}}
const PRIMARY_KPIS=[
  {key:'assignment_rate',name:'업무 배정 완료율',unit:'%',target:100,desc:'등록된 모든 업무에 담당자와 기한이 지정됐는지 확인'},
  {key:'assignment_time',name:'평균 담당자 배정 시간',unit:'일',target:1,desc:'업무 등록 후 담당자 지정까지 걸린 평균 시간'},
  {key:'assignment_fit',name:'업무 배정 적합도',unit:'점',target:4,desc:'업무량·난이도가 적절했는지 구성원 응답으로 확인'}
];
function primaryKpiValue(key){if(key==='assignment_rate'){const total=data.tasks.length;return total?Math.round(data.tasks.filter(t=>t.owner&&t.owner!=='미정'&&t.due).length/total*100):0}if(key==='assignment_time'){const values=data.tasks.filter(t=>t.assignmentHours!=null).map(t=>Number(t.assignmentHours)).filter(Number.isFinite);return values.length?Math.round(values.reduce((a,v)=>a+v,0)/values.length*10)/10:'—'}const responses=data.satisfaction||[];if(!responses.length)return '—';const fit={적절:4,쉬움:3,어려움:2};const load={적정:4,여유:3,과다:2};const scores=responses.map(x=>((fit[x.fit]||3)+(load[x.load]||3))/2);return Math.round(scores.reduce((a,v)=>a+v,0)/scores.length*10)/10}
function primaryKpiStatus(kpi,value){if(value==='—')return '입력 대기';if(kpi.key==='assignment_time')return value<=kpi.target?'목표 달성':'개선 필요';return value>=kpi.target?'목표 달성':'진행 중'}
function records(){const list=[...data.entries.map(e=>({...e,type:'quant'})),...data.notes.map(n=>({...n,type:'qual'}))].sort((a,b)=>b.id-a.id);return `<section class="view">${heading('KPI 현황','KPI CONTROL CENTER','우리 과제의 핵심 성과를 먼저 확인하고, 기존 기록은 부가 자료로 관리합니다.','<button class="btn secondary" onclick="downloadCSV()">기록 CSV</button>')}<div class="primary-kpi-grid">${PRIMARY_KPIS.map(k=>{const value=primaryKpiValue(k.key);const status=primaryKpiStatus(k,value);const progress=value==='—'?0:k.key==='assignment_time'?Math.min(100,Math.round(k.target/Math.max(value,0.1)*100)):Math.min(100,Math.round(value/k.target*100));return `<article class="primary-kpi-card ${status==='목표 달성'?'hit':status==='입력 대기'?'pending':'active'}"><div class="primary-kpi-head"><span>${k.name}</span><b>${status}</b></div><div class="primary-kpi-value">${value}<em>${k.unit}</em></div><div class="primary-kpi-target">목표 ${k.target}${k.unit} · ${k.desc}</div><div class="primary-progress"><span style="width:${progress}%"></span></div></article>`}).join('')}</div><div class="kpi-layout"><div class="form-card"><h2>성과 기록 입력</h2><p>핵심 KPI 또는 기존 부가 지표를 선택해 기록합니다.</p><form id="recordForm"><div class="field"><label>기록 유형</label><select id="recordType"><option value="quant">정량 실적</option><option value="qual">정성 기록</option></select></div><div class="field"><label>지표</label><select id="metric"><optgroup label="핵심 KPI">${PRIMARY_KPIS.map(k=>`<option value="${k.name}">${k.name}</option>`).join('')}</optgroup><optgroup label="부가 지표"><option value="담당이 정해진 비율">기존 담당이 정해진 비율</option><option value="정성 기록">정성 기록</option></optgroup></select></div><div class="field" id="valueField"><label>실적 값</label><input id="value" type="number" min="0" max="100" step="0.1" placeholder="숫자 입력" /></div><div class="field"><label>기록일</label><input id="date" type="date" value="${today}" required /></div><div class="field"><label id="noteLabel">메모</label><textarea id="note" placeholder="변화, 근거, 관찰 내용을 적어주세요."></textarea></div><div class="field" id="photoField" style="display:none"><label>사진 주소</label><input id="photoUrl" type="url" placeholder="https://..." /></div><button class="btn" type="submit">성과 기록 저장</button></form></div><div class="secondary-kpi-area"><div class="section-row compact"><div><h2>부가 기록</h2><p>기존 정량·정성 기록을 참고 자료로 확인합니다.</p></div><span class="secondary-badge">${list.length}건</span></div><div class="record-list">${list.map(recordItem).join('')||'<div class="empty">부가 기록이 없습니다.</div>'}</div></div></div></section>`}
function autoAssignTask(id){const t=data.tasks.find(x=>x.id===id);if(!t)return;const candidate=bestCandidate(t);if(!candidate)return toast('추천 가능한 구성원이 없습니다.');const old=t.owner;t.owner=candidate.name;t.status='assigned';const member=data.members.find(m=>m.name===candidate.name);if(member)member.workload=Math.min(100,Math.round(member.workload+(t.estimatedHours||8)/40*100));const created=new Date(t.createdAt||today);const assigned=new Date(today);t.assignedAt=today;t.assignmentHours=Math.max(0,Math.round(((assigned-created)/86400000||0.5)*10)/10);data.history.push({id:Date.now(),taskId:t.id,taskTitle:t.title,previousOwner:old,newOwner:candidate.name,changedAt:today,method:'auto',score:candidate.score});save();toast(`${candidate.name}님에게 자동 배정했습니다.`);render()}
const DIFFICULTY_WEIGHT={하:1,중:1.1,상:1.25,최상:1.4};
function taskLoadHours(task,member){const required=task.requiredSkills||[];const matched=required.filter(s=>(member.skills||[]).includes(s)).length;const efficiency=required.length?1-(matched/required.length*.15):1;return (Number(task.estimatedHours)||0)*(DIFFICULTY_WEIGHT[task.difficulty]||1)*efficiency}
function calculatedWorkload(member){if(!member)return 0;const active=data.tasks.filter(t=>t.owner===member.name&&!['done','unassigned'].includes(t.status));const weightedHours=active.reduce((sum,t)=>sum+taskLoadHours(t,member),0);const capacity=(Number(member.capacityHours)||24)*Math.max(.25,Math.min(1,Number(member.availability)||1));return Math.min(150,Math.round(weightedHours/capacity*100))}
function syncComputedWorkloads(){data.members.forEach(m=>{m.workload=calculatedWorkload(m)})}
function workload(name){return calculatedWorkload(data.members.find(m=>m.name===name))}
function recommend(t){const required=(t.requiredSkills||[]).filter(Boolean);return data.members.map(m=>{const current=calculatedWorkload(m);const typeMatch=(m.types||[]).includes(t.taskType)?30:0;const skillHits=required.filter(s=>(m.skills||[]).includes(s)).length;const skillScore=required.length?Math.round(skillHits/required.length*30):15;const levelScore=levelRank(m.level)>=levelRank(t.requiredLevel||t.difficulty)?20:5;const expScore=m.experience>=(t.minExperience||0)?10:Math.max(0,10-Math.round(((t.minExperience||0)-m.experience)*2));const capacityScore=Math.max(0,10-Math.round(current/10));const score=Math.max(0,Math.round(typeMatch+skillScore+levelScore+expScore+capacityScore));const projected=Math.round((current+(taskLoadHours(t,m)/((Number(m.capacityHours)||24)*Math.max(.25,Number(m.availability)||1))*100)));const eligible=current<(m.maxWorkload||85)&&projected<=(m.maxWorkload||85);return {...m,workload:current,projectedWorkload:projected,score,eligible,breakdown:{type:typeMatch,skills:skillScore,level:levelScore,experience:expScore,capacity:capacityScore},skillHits}}).sort((a,b)=>(Number(b.eligible)-Number(a.eligible))||b.score-a.score)}
function bestCandidate(t){return recommend(t).find(m=>m.eligible)||recommend(t)[0]}
document.addEventListener('change',e=>{if(e.target.name==='level'&&e.target.form?.id==='taskModalForm'){const d=GRADE_DEFAULTS[e.target.value];e.target.form.querySelectorAll('input[name="skills"]').forEach(x=>x.checked=d.skills.includes(x.value));if(e.target.form.elements.experience)e.target.form.elements.experience.value=d.experience}if(e.target.id==='metric'){const score=e.target.value==='업무 배정 적합도';const input=$('#value');if(input){input.max=score?5:100;input.step=score?0.1:1;input.placeholder=score?'예: 4.0':'숫자 입력'}}});
function openTaskDetail(id){const t=data.tasks.find(x=>x.id===id);if(!t)return;const candidates=recommend(t).slice(0,3);$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal detail-modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><div class="detail-top"><div><span class="status ${t.status}">${statusLabel(t.status)}</span><p class="eyebrow">WORK ITEM DETAIL</p><h2>${esc(t.title)}</h2><p class="modal-help">${esc(t.description||'설명 없음')}</p></div><div class="detail-hours"><strong>${t.estimatedHours||0}h</strong><small>예상 소요</small></div></div><div class="detail-grid"><div><label>업무 종류</label><strong>${esc(t.taskType||'미지정')}</strong><small>업무 분류</small></div><div><label>난이도</label><strong>${esc(t.difficulty||t.requiredLevel||'미지정')}</strong><small>필요 직급 ${esc(t.requiredLevel||'미지정')}</small></div><div><label>담당자</label><strong>${esc(t.owner)}</strong><small>${t.owner==='미정'?'자동 배정 대기':'현재 자동 계산 부하 '+workload(t.owner)+'%'}</small></div><div><label>기한</label><strong>${t.due||'미지정'}</strong><small>${t.due&&t.due<today?'기한 초과':'기한 내'}</small></div></div><div class="detail-section"><div class="detail-section-head"><label>추천 후보</label><small>업무 종류·역량·직급·경력·자동 부하 반영</small></div><div class="candidate-list">${candidates.map((m,i)=>`<div class="candidate-row"><span class="candidate-rank">${i+1}</span><div><strong>${esc(m.name)}</strong><small>${esc(m.level)} · ${m.skills.slice(0,3).join(' · ')}</small></div><b>${m.score}점</b><em>현재 ${m.workload}% · 배정 후 ${m.projectedWorkload}%</em></div>`).join('')||'<div class="empty">추천 후보 없음</div>'}</div></div><div class="detail-section"><label>상태 변경</label><div class="status-actions">${['unassigned','assigned','in_progress','blocked','done'].map(s=>`<button class="status-choice ${s===t.status?'selected':''}" onclick="changeTaskStatus(${id},'${s}')">${statusLabel(s)}</button>`).join('')}</div></div><div class="modal-actions"><button class="btn secondary" onclick="closeModal()">닫기</button>${t.status==='unassigned'?`<button class="btn" onclick="autoAssignTask(${id})">자동 배정</button>`:''}</div></section></div>`}
document.querySelectorAll('.nav-item').forEach(x=>x.onclick=()=>go(x.dataset.view));$('#resetData').onclick=()=>{data=JSON.parse(JSON.stringify(seed));data.members=data.members.map(m=>{const d=GRADE_DEFAULTS[m.level]||GRADE_DEFAULTS['사원'];return {...m,types:d.types,skills:d.skills,capabilities:d.skills,maxWorkload:d.maxWorkload,capacityHours:d.capacityHours,availability:d.availability,profileSource:'grade_default'}});data.tasks=data.tasks.map(t=>({...t,taskType:'교육 운영',difficulty:t.requiredLevel}));save();render();toast('샘플 데이터로 초기화했습니다.')};render();
function openMemberEditor(name){const m=data.members.find(x=>x.name===name);if(!m)return;const d=GRADE_DEFAULTS[m.level]||GRADE_DEFAULTS['사원'];$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><p class="eyebrow">CAPABILITY SETTINGS</p><h2>${esc(m.name)} 업무 가능량</h2><p class="modal-help">현재 부하율은 배정된 진행 업무에서 자동 계산됩니다. 아래 값은 개인별 업무 가능량 설정입니다.</p><div class="computed-load-callout"><span>현재 자동 계산 부하</span><strong>${calculatedWorkload(m)}%</strong><small>예상시간 · 난이도 · 역량 적합도 반영</small></div><form id="memberForm" class="modal-form"><div class="form-grid"><div class="field"><label>직급</label><select name="level" id="memberLevel">${TASK_LEVELS.map(x=>`<option ${m.level===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>경력(년)</label><input name="experience" type="number" min="0" value="${m.experience||d.experience}"></div><div class="field"><label>주당 업무 가능시간</label><input name="capacityHours" type="number" min="1" max="60" value="${m.capacityHours||d.capacityHours}"></div><div class="field"><label>이번 기간 가용 비율(%)</label><input name="availability" type="number" min="25" max="100" value="${Math.round((m.availability||1)*100)}"></div><div class="field"><label>배정 허용 상한(%)</label><input name="maxWorkload" type="number" min="50" max="150" value="${m.maxWorkload||d.maxWorkload}"></div><div class="field full-field grade-default-row"><span class="grade-default-hint">${m.level} 기본값: 주당 ${d.capacityHours}시간 · 가용 ${Math.round(d.availability*100)}%</span><button type="button" class="text-btn" id="resetGradeDefaults">직급 기본값 적용</button></div><div class="field full-field"><label>수행 가능 업무 종류</label><div class="check-grid">${TASK_TYPES.map(x=>`<label class="check-chip"><input type="checkbox" name="types" value="${x}" ${(m.types||d.types).includes(x)?'checked':''}><span>${x}</span></label>`).join('')}</div></div><div class="field full-field"><label>보유 역량</label><div class="check-grid">${SKILL_LIBRARY.map(x=>`<label class="check-chip"><input type="checkbox" name="skills" value="${x}" ${(m.skills||d.skills).includes(x)?'checked':''}><span>${x}</span></label>`).join('')}</div></div></div><div class="modal-actions"><button type="button" class="btn secondary" onclick="closeModal()">취소</button><button class="btn" type="submit">설정 저장</button></div></form></section></div>`;const form=$('#memberForm');const apply=()=>{const next=GRADE_DEFAULTS[$('#memberLevel').value];form.elements.experience.value=next.experience;form.elements.capacityHours.value=next.capacityHours;form.elements.availability.value=Math.round(next.availability*100);form.elements.maxWorkload.value=next.maxWorkload;form.querySelectorAll('input[name="types"]').forEach(x=>x.checked=next.types.includes(x.value));form.querySelectorAll('input[name="skills"]').forEach(x=>x.checked=next.skills.includes(x.value));form.querySelector('.grade-default-hint').textContent=`${$('#memberLevel').value} 기본값: 주당 ${next.capacityHours}시간 · 가용 ${Math.round(next.availability*100)}%`};$('#memberLevel').onchange=apply;$('#resetGradeDefaults').onclick=apply;form.onsubmit=e=>{e.preventDefault();const f=new FormData(form);m.level=String(f.get('level'));m.experience=Number(f.get('experience'))||0;m.capacityHours=Number(f.get('capacityHours'))||d.capacityHours;m.availability=Math.max(.25,Math.min(1,Number(f.get('availability'))/100||1));m.maxWorkload=Math.max(50,Math.min(150,Number(f.get('maxWorkload'))||d.maxWorkload));m.types=f.getAll('types');m.skills=f.getAll('skills');m.capabilities=m.skills;m.profileSource='individual';syncComputedWorkloads();save();closeModal();toast('개인별 업무 가능량을 저장했습니다.');render()}}
function confirmAssignTask(id,name){const t=data.tasks.find(x=>x.id===id);const m=data.members.find(x=>x.name===name);if(!t||!m)return;const old=t.owner;t.owner=name;t.status='assigned';const created=new Date(t.createdAt||today);const assigned=new Date(today);t.assignedAt=today;t.assignmentHours=Math.max(.5,Math.round(((assigned-created)/86400000||.5)*10)/10);data.history.push({id:Date.now(),taskId:id,taskTitle:t.title,previousOwner:old,newOwner:name,changedAt:today,method:'manual'});syncComputedWorkloads();save();closeModal();toast(`${name}님에게 배정했습니다.`);render()}
function openAssignModal(id){const t=data.tasks.find(x=>x.id===id);if(!t)return;const candidates=recommend(t).slice(0,5);$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal assign-modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><p class="eyebrow">ASSIGN WORK</p><h2>담당자 선택</h2><p class="modal-help"><b>${esc(t.title)}</b> · 추천 점수와 배정 후 부하를 비교하세요.</p><div class="assign-candidates">${candidates.map((m,i)=>`<button class="assign-candidate ${m.eligible?'eligible':'overload'}" onclick="confirmAssignTask(${id},'${esc(m.name)}')"><span class="candidate-rank">${i+1}</span><span class="assign-person"><strong>${esc(m.name)}</strong><small>${esc(m.level)} · ${(m.skills||[]).slice(0,3).join(' · ')}</small></span><span class="assign-score"><b>${m.score}점</b><small>현재 ${m.workload}% · 배정 후 ${m.projectedWorkload}%</small></span><span class="assign-state">${m.eligible?'배정 가능':'상한 초과'}</span></button>`).join('')||'<div class="empty">추천 후보가 없습니다.</div>'}</div><div class="modal-actions"><button class="btn secondary" onclick="closeModal()">취소</button><button class="btn" onclick="autoAssignTask(${id})">1순위 자동 배정</button></div></section></div>`}
function assignTask(id){openAssignModal(id)}
function openSatisfaction(id){const t=data.tasks.find(x=>x.id===id);if(!t)return;$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><p class="eyebrow">WORK FEEDBACK</p><h2>업무 만족도 기록</h2><p class="modal-help">${esc(t.title)} · ${esc(t.owner)}</p><form id="satisfactionForm" class="modal-form"><div class="field"><label>업무 수준</label><div class="choice-row"><label><input type="radio" name="fit" value="적절" checked><span>적절</span></label><label><input type="radio" name="fit" value="쉬움"><span>쉬움</span></label><label><input type="radio" name="fit" value="어려움"><span>어려움</span></label></div></div><div class="field"><label>업무 부하</label><div class="choice-row"><label><input type="radio" name="load" value="적정" checked><span>적정</span></label><label><input type="radio" name="load" value="여유"><span>여유</span></label><label><input type="radio" name="load" value="과다"><span>과다</span></label></div></div><div class="field"><label>더 높은 난이도 업무</label><div class="choice-row"><label><input type="radio" name="challenge" value="예" checked><span>가능</span></label><label><input type="radio" name="challenge" value="아니오"><span>현재 수준 유지</span></label></div></div><div class="field"><label>추가 의견</label><textarea name="comment" placeholder="지원이 필요했던 점, 다음 배정에 반영할 점"></textarea></div><div class="modal-actions"><button type="button" class="btn secondary" onclick="closeModal()">취소</button><button class="btn" type="submit">만족도 저장</button></div></form></section></div>`;$('#satisfactionForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const record={id:Date.now(),taskId:id,taskTitle:t.title,owner:t.owner,fit:String(f.get('fit')),load:String(f.get('load')),challenge:String(f.get('challenge')),comment:String(f.get('comment')||''),date:today};data.satisfaction.push(record);cloudRequest('rr_task_satisfaction','POST',{task_id:id,owner_name:t.owner,fit:record.fit,workload_feedback:record.load,challenge_preference:record.challenge,comment:record.comment,recorded_on:today});save();closeModal();toast('업무 만족도를 저장했습니다.');render()}}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#modalRoot')?.innerHTML)closeModal()});
function autoAssignAll(){const pending=data.tasks.filter(t=>t.status==='unassigned');if(!pending.length)return toast('미배정 업무가 없습니다.');let assigned=0;pending.forEach(t=>{const c=bestCandidate(t);if(!c||!c.eligible)return;const old=t.owner;t.owner=c.name;t.status='assigned';const created=new Date(t.createdAt||today);const assignedDate=new Date(today);t.assignedAt=today;t.assignmentHours=Math.max(.5,Math.round(((assignedDate-created)/86400000||.5)*10)/10);data.history.push({id:Date.now()+assigned,taskId:t.id,taskTitle:t.title,previousOwner:old,newOwner:c.name,changedAt:today,method:'auto-bulk',score:c.score});assigned++});syncComputedWorkloads();save();toast(`${assigned}건 자동 배정했습니다.`);render()}
function dashboardExtras(){const pending=data.tasks.filter(t=>t.status==='unassigned').length;const active=data.tasks.filter(t=>['assigned','in_progress','blocked'].includes(t.status)).length;const done=data.tasks.filter(t=>t.status==='done').length;const urgent=data.tasks.filter(t=>t.status==='blocked'||(t.due&&t.due<='2026-08-21')).slice(0,3);return `<div class="workflow-panel"><div class="workflow-head"><div><p class="eyebrow">NEXT ACTION</p><h2>이번 주 업무 흐름</h2><p>현황을 확인하고 다음 액션을 바로 실행하세요.</p></div><div class="workflow-actions"><button class="btn secondary" onclick="go('records')">KPI 기록</button>${pending?`<button class="btn" onclick="autoAssignAll()">미배정 ${pending}건 자동 배정</button>`:''}</div></div><div class="workflow-steps"><button onclick="go('tasks');taskStatus='unassigned';render()" class="workflow-step ${pending?'attention':''}"><span>01</span><b>미배정 확인</b><strong>${pending}</strong><small>담당자 대기</small></button><button onclick="go('tasks');taskStatus='assigned';render()" class="workflow-step"><span>02</span><b>배정 완료</b><strong>${data.tasks.filter(t=>t.status==='assigned').length}</strong><small>업무 시작 전</small></button><button onclick="go('tasks');taskStatus='in_progress';render()" class="workflow-step"><span>03</span><b>진행 중</b><strong>${active}</strong><small>진행·막힘 포함</small></button><button onclick="go('tasks');taskStatus='done';render()" class="workflow-step"><span>04</span><b>완료</b><strong>${done}</strong><small>성과 기록 대상</small></button></div></div><div class="dashboard-extras"><div class="panel"><div class="panel-header"><div><div class="panel-title">우선 확인</div><div class="panel-desc">막힘·기한 임박 업무</div></div><button class="text-btn" onclick="go('tasks')">전체 업무 →</button></div><div class="attention-list">${urgent.map(t=>`<button class="attention-item" onclick="openTaskDetail(${t.id})"><span class="attention-dot ${t.status}"></span><span><b>${esc(t.title)}</b><small>${t.status==='blocked'?'막힘 상태':'마감 '+t.due}</small></span><span>›</span></button>`).join('')||'<div class="empty">긴급 확인 업무 없음</div>'}</div></div><div class="panel"><div class="panel-header"><div><div class="panel-title">팀 업무부하</div><div class="panel-desc">자동 배정 판단 기준</div></div><button class="text-btn" onclick="go('team')">팀원 보기 →</button></div><div class="load-list">${data.members.map(m=>{const current=calculatedWorkload(m);const color=current>=80?'high':current>=60?'mid':'ok';return `<div class="load-row"><div class="load-person"><span class="owner-avatar">${esc(m.name[0])}</span><b>${esc(m.name)}</b><small>${m.level}</small></div><div class="load-bar"><span class="${color}" style="width:${Math.min(100,current)}%"></span></div><strong class="load-value ${color}">${current}%</strong></div>`}).join('')}</div></div></div>`}
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();go('tasks');setTimeout(()=>$('#taskSearch')?.focus(),0)}});
function currentUserName(){return data.currentUser||data.members[0]?.name||''}
function canSubmitSatisfaction(task){return Boolean(task&&task.owner&&task.owner!=='미정'&&task.owner===currentUserName())}
function openSatisfaction(id){const t=data.tasks.find(x=>x.id===id);if(!t)return;if(!canSubmitSatisfaction(t))return toast('업무를 실제 수행한 담당자만 만족도를 입력할 수 있습니다.');$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><p class="eyebrow">WORK FEEDBACK</p><h2>업무 만족도 기록</h2><p class="modal-help">${esc(t.title)} · ${esc(t.owner)}님 본인 입력</p><form id="satisfactionForm" class="modal-form"><div class="field"><label>업무 수준</label><div class="choice-row"><label><input type="radio" name="fit" value="적절" checked><span>적절</span></label><label><input type="radio" name="fit" value="쉬움"><span>쉬움</span></label><label><input type="radio" name="fit" value="어려움"><span>어려움</span></label></div></div><div class="field"><label>업무 부하</label><div class="choice-row"><label><input type="radio" name="load" value="적정" checked><span>적정</span></label><label><input type="radio" name="load" value="여유"><span>여유</span></label><label><input type="radio" name="load" value="과다"><span>과다</span></label></div></div><div class="field"><label>더 높은 난이도 업무</label><div class="choice-row"><label><input type="radio" name="challenge" value="예" checked><span>가능</span></label><label><input type="radio" name="challenge" value="아니오"><span>현재 수준 유지</span></label></div></div><div class="field"><label>추가 의견</label><textarea name="comment" placeholder="지원이 필요했던 점, 다음 배정에 반영할 점"></textarea></div><div class="modal-actions"><button type="button" class="btn secondary" onclick="closeModal()">취소</button><button class="btn" type="submit">만족도 저장</button></div></form></section></div>`;$('#satisfactionForm').onsubmit=e=>{e.preventDefault();if(!canSubmitSatisfaction(t))return toast('담당자 본인만 저장할 수 있습니다.');const f=new FormData(e.target);const record={id:Date.now(),taskId:id,taskTitle:t.title,owner:t.owner,submittedBy:currentUserName(),fit:String(f.get('fit')),load:String(f.get('load')),challenge:String(f.get('challenge')),comment:String(f.get('comment')||''),date:today};data.satisfaction.push(record);cloudRequest('rr_task_satisfaction','POST',{task_id:id,owner_name:t.owner,submitted_by:currentUserName(),fit:record.fit,workload_feedback:record.load,challenge_preference:record.challenge,comment:record.comment,recorded_on:today});save();closeModal();toast('본인 업무 만족도를 저장했습니다.');render()}}
function taskCard(t){const due=t.due?.slice(5).replace('-','.');const candidate=t.status==='unassigned'?bestCandidate(t):null;const feedback=canSubmitSatisfaction(t)?`<button class="satisfaction-btn" onclick="openSatisfaction(${t.id})">내 업무 만족도 남기기</button>`:`<span class="owner-only-note">만족도: 담당자 본인만 입력</span>`;return `<article class="task-tile ${t.status}"><div class="task-head"><button class="status ${t.status}" onclick="openTaskDetail(${t.id})">${statusLabel(t.status)}</button><span class="priority">${esc(t.taskType||'업무')} · ${esc(t.difficulty||'')} · ${t.estimatedHours||0}h</span></div><button class="task-title-button" onclick="openTaskDetail(${t.id})"><h3>${esc(t.title)}</h3></button><p class="task-meta">${esc(t.description)}</p><div class="task-tags">${(t.requiredSkills||[]).map(s=>`<span>역량 · ${esc(s)}</span>`).join('')}${(t.collaborators||[]).map(c=>`<span>협업 · ${esc(c)}</span>`).join('')}</div><div class="task-footer"><span class="owner-chip"><span class="mini-avatar">${t.owner==='미정'?'?':esc(t.owner[0])}</span>${esc(t.owner)}${t.owner!=='미정'?`<small>부하 ${workload(t.owner)}%</small>`:''}</span><span class="date">마감 ${due}</span></div>${t.status==='unassigned'?`<div class="recommend-box"><span>추천 후보 <b>${candidate?esc(candidate.name):'없음'}</b><small>${candidate?`적합도 ${candidate.score}점 · 배정 후 ${candidate.projectedWorkload}%`:''}</small></span><button class="auto-assign-btn" onclick="autoAssignTask(${t.id})">자동 배정</button></div>`:feedback}</article>`}
function currentUserName(){return window.RR_CURRENT_USER||data.currentUser||data.members[0]?.name||''}
function saveStatusChange(id,status,reason){const t=data.tasks.find(x=>x.id===id);if(!t)return;const old=t.status;if(old===status){closeModal();return}t.status=status;data.history.push({id:Date.now(),kind:'status',taskId:id,taskTitle:t.title,previousStatus:old,newStatus:status,previousOwner:statusLabel(old),newOwner:statusLabel(status),reason:reason||'',changedBy:currentUserName(),changedAt:today});syncComputedWorkloads();save();closeModal();toast(`${statusLabel(status)} 상태로 변경했습니다.`);render()}
function changeTaskStatus(id,status){const t=data.tasks.find(x=>x.id===id);if(!t)return;openStatusModal(id,status||t.status)}
function quickStatusChange(id,status){const t=data.tasks.find(x=>x.id===id);if(!t)return;openStatusModal(id,status)}
function openStatusModal(id,status){const t=data.tasks.find(x=>x.id===id);if(!t)return;$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal status-modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><p class="eyebrow">UPDATE STATUS</p><h2>업무 상태 변경</h2><p class="modal-help">${esc(t.title)} · 현재 ${statusLabel(t.status)}</p><form id="statusForm" class="modal-form"><div class="field"><label>변경할 상태</label><select name="status">${['unassigned','assigned','in_progress','blocked','done'].map(s=>`<option value="${s}" ${status===s?'selected':''}>${statusLabel(s)}</option>`).join('')}</select></div><div class="field"><label>변경 사유 <span class="optional">선택</span></label><textarea name="reason" placeholder="예: 담당자 확인 완료, 협업 부서 회신 대기, 결과물 검토 완료"></textarea></div><div class="status-history-mini"><label>최근 변경</label>${data.history.filter(h=>h.taskId===id&&h.kind==='status').slice(-3).reverse().map(h=>`<p><b>${statusLabel(h.previousStatus)}</b> → <b>${statusLabel(h.newStatus)}</b><small>${h.changedAt}${h.reason?' · '+esc(h.reason):''}</small></p>`).join('')||'<p class="empty">아직 상태 변경 이력이 없습니다.</p>'}</div><div class="modal-actions"><button type="button" class="btn secondary" onclick="closeModal()">취소</button><button class="btn" type="submit">상태 저장</button></div></form></section></div>`;$('#statusForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);saveStatusChange(id,String(f.get('status')),String(f.get('reason')||''))}}
function taskCard(t){const due=t.due?.slice(5).replace('-','.');const candidate=t.status==='unassigned'?bestCandidate(t):null;const feedback=canSubmitSatisfaction(t)?`<button class="satisfaction-btn" onclick="openSatisfaction(${t.id})">내 업무 만족도 남기기</button>`:`<span class="owner-only-note">만족도: 담당자 본인만 입력</span>`;return `<article class="task-tile ${t.status}"><div class="task-head"><select class="status-select ${t.status}" aria-label="${esc(t.title)} 상태" onclick="event.stopPropagation()" onchange="quickStatusChange(${t.id},this.value)">${['unassigned','assigned','in_progress','blocked','done'].map(s=>`<option value="${s}" ${t.status===s?'selected':''}>${statusLabel(s)}</option>`).join('')}</select><span class="priority">${esc(t.taskType||'업무')} · ${esc(t.difficulty||'')} · ${t.estimatedHours||0}h</span></div><button class="task-title-button" onclick="openTaskDetail(${t.id})"><h3>${esc(t.title)}</h3></button><p class="task-meta">${esc(t.description)}</p><div class="task-tags">${(t.requiredSkills||[]).map(s=>`<span>역량 · ${esc(s)}</span>`).join('')}${(t.collaborators||[]).map(c=>`<span>협업 · ${esc(c)}</span>`).join('')}</div><div class="task-footer"><span class="owner-chip"><span class="mini-avatar">${t.owner==='미정'?'?':esc(t.owner[0])}</span>${esc(t.owner)}${t.owner!=='미정'?`<small>부하 ${workload(t.owner)}%</small>`:''}</span><span class="date">마감 ${due}</span></div>${t.status==='unassigned'?`<div class="recommend-box"><span>추천 후보 <b>${candidate?esc(candidate.name):'없음'}</b><small>${candidate?`적합도 ${candidate.score}점 · 배정 후 ${candidate.projectedWorkload}%`:''}</small></span><button class="auto-assign-btn" onclick="autoAssignTask(${t.id})">자동 배정</button></div>`:feedback}</article>`}
function isAdminUser(){const user=data.members.find(m=>m.name===currentUserName());return window.RR_IS_ADMIN===true||data.currentUserRole==='admin'||user?.level==='G3'}
function saveStatusChange(id,status,reason){const t=data.tasks.find(x=>x.id===id);if(!t)return;const old=t.status;const cleanReason=String(reason||'').trim();if(old!=='unassigned'&&status==='unassigned'&&!isAdminUser())return toast('배정된 업무를 담당 미정으로 바꾸는 권한이 없습니다. 관리자만 변경할 수 있습니다.');if(old===status){closeModal();return}if(!cleanReason){toast('상태 변경 사유를 입력해야 저장할 수 있습니다.');return}t.status=status;data.history.push({id:Date.now(),kind:'status',taskId:id,taskTitle:t.title,previousStatus:old,newStatus:status,previousOwner:statusLabel(old),newOwner:statusLabel(status),reason:cleanReason,changedBy:currentUserName(),changedAt:today});syncComputedWorkloads();save();closeModal();toast(`${statusLabel(status)} 상태로 변경했습니다.`);render()}
function quickStatusChange(id,status){const t=data.tasks.find(x=>x.id===id);if(!t)return;if(t.status!=='unassigned'&&status==='unassigned'&&!isAdminUser()){toast('배정된 업무를 담당 미정으로 바꾸는 권한이 없습니다.');render();return}openStatusModal(id,status)}
