function openStatusModal(id,status){const t=data.tasks.find(x=>x.id===id);if(!t)return;const canUnassign=isAdminUser()||t.status==='unassigned';$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal status-modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><p class="eyebrow">UPDATE STATUS</p><h2>업무 상태 변경</h2><p class="modal-help">${esc(t.title)} · 현재 ${statusLabel(t.status)}</p><form id="statusForm" class="modal-form"><div class="field"><label>변경할 상태</label><select name="status">${['unassigned','assigned','in_progress','blocked','done'].map(s=>`<option value="${s}" ${status===s?'selected':''} ${s==='unassigned'&&!canUnassign?'disabled':''}>${statusLabel(s)}${s==='unassigned'&&!canUnassign?' · 관리자만 가능':''}</option>`).join('')}</select></div><div class="field"><label>변경 사유 <em>* 필수</em></label><textarea name="reason" required placeholder="상태를 변경하는 이유를 입력하세요."></textarea><small class="field-help">사유를 입력해야 상태 변경 이력이 저장됩니다.</small></div><div class="status-history-mini"><label>최근 변경 이력</label>${data.history.filter(h=>h.taskId===id&&h.kind==='status').slice(-3).reverse().map(h=>`<p><b>${statusLabel(h.previousStatus)}</b> → <b>${statusLabel(h.newStatus)}</b><small>${h.changedAt} · ${esc(h.changedBy||'시스템')}${h.reason?' · '+esc(h.reason):''}</small></p>`).join('')||'<p class="empty">아직 상태 변경 이력이 없습니다.</p>'}</div><div class="modal-actions"><button type="button" class="btn secondary" onclick="closeModal()">취소</button><button class="btn" type="submit">사유와 함께 저장</button></div></form></section></div>`;$('#statusForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const reason=String(f.get('reason')||'').trim();if(!reason){$('#statusForm [name="reason"]').focus();toast('변경 사유를 입력해야 저장할 수 있습니다.');return}saveStatusChange(id,String(f.get('status')),reason)}}
function taskCard(t){const due=t.due?.slice(5).replace('-','.');const candidate=t.status==='unassigned'?bestCandidate(t):null;const feedback=canSubmitSatisfaction(t)?`<button class="satisfaction-btn" onclick="openSatisfaction(${t.id})">내 업무 만족도 남기기</button>`:`<span class="owner-only-note">만족도: 담당자 본인만 입력</span>`;const statusOptions=['unassigned','assigned','in_progress','blocked','done'].map(s=>`<option value="${s}" ${t.status===s?'selected':''} ${s==='unassigned'&&t.status!=='unassigned'&&!isAdminUser()?'disabled':''}>${statusLabel(s)}</option>`).join('');return `<article class="task-tile ${t.status}"><div class="task-head"><select class="status-select ${t.status}" aria-label="${esc(t.title)} 상태" onclick="event.stopPropagation()" onchange="quickStatusChange(${t.id},this.value)">${statusOptions}</select><span class="priority">${esc(t.taskType||'업무')} · ${esc(t.difficulty||'')} · ${t.estimatedHours||0}h</span></div><button class="task-title-button" onclick="openTaskDetail(${t.id})"><h3>${esc(t.title)}</h3></button><p class="task-meta">${esc(t.description)}</p><div class="task-tags">${(t.requiredSkills||[]).map(s=>`<span>역량 · ${esc(s)}</span>`).join('')}${(t.collaborators||[]).map(c=>`<span>협업 · ${esc(c)}</span>`).join('')}</div><div class="task-footer"><span class="owner-chip"><span class="mini-avatar">${t.owner==='미정'?'?':esc(t.owner[0])}</span>${esc(t.owner)}${t.owner!=='미정'?`<small>부하 ${workload(t.owner)}%</small>`:''}</span><span class="date">마감 ${due}</span></div>${t.status==='unassigned'?`<div class="recommend-box"><span>추천 후보 <b>${candidate?esc(candidate.name):'없음'}</b><small>${candidate?`적합도 ${candidate.score}점 · 배정 후 ${candidate.projectedWorkload}%`:''}</small></span><button class="auto-assign-btn" onclick="autoAssignTask(${t.id})">자동 배정</button></div>`:feedback}</article>`}
function openStatusModal(id,status){const t=data.tasks.find(x=>x.id===id);if(!t)return;const canUnassign=isAdminUser()||t.status==='unassigned';$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal status-modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><p class="eyebrow">UPDATE STATUS</p><h2>업무 상태 변경</h2><p class="modal-help">${esc(t.title)} · 현재 ${statusLabel(t.status)}</p><form id="statusForm" class="modal-form"><div class="field"><label>변경할 상태</label><select name="status">${['unassigned','assigned','in_progress','blocked','done'].map(s=>`<option value="${s}" ${status===s?'selected':''} ${s==='unassigned'&&!canUnassign?'disabled':''}>${statusLabel(s)}${s==='unassigned'&&!canUnassign?' · 관리자만 가능':''}</option>`).join('')}</select></div><div class="field"><label>변경/전환 이력 <em>* 필수</em></label><textarea name="reason" required placeholder="상태 변경 또는 전환 내용을 입력하세요."></textarea><small class="field-help">변경/전환 이력을 입력해야 상태가 저장됩니다.</small></div><div class="status-history-mini"><label>최근 변경/전환 이력</label>${data.history.filter(h=>h.taskId===id&&h.kind==='status').slice(-3).reverse().map(h=>`<p><b>${statusLabel(h.previousStatus)}</b> → <b>${statusLabel(h.newStatus)}</b><small>${h.changedAt} · ${esc(h.changedBy||'시스템')}${h.reason?' · '+esc(h.reason):''}</small></p>`).join('')||'<p class="empty">아직 변경/전환 이력이 없습니다.</p>'}</div><div class="modal-actions"><button type="button" class="btn secondary" onclick="closeModal()">취소</button><button class="btn" type="submit">이력과 함께 저장</button></div></form></section></div>`;$('#statusForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const history=String(f.get('reason')||'').trim();if(!history){$('#statusForm [name="reason"]').focus();toast('변경/전환 이력을 입력해야 저장할 수 있습니다.');return}saveStatusChange(id,String(f.get('status')),history)}}
function quickStatusChange(id,status){const t=data.tasks.find(x=>x.id===id);if(!t)return;if(t.status!=='unassigned'&&status==='unassigned'&&!isAdminUser()){toast('배정된 업무를 담당 미정으로 바꾸는 권한이 없습니다.');render();return}openStatusModal(id,status);render()}
function changeTaskStatus(id,status){quickStatusChange(id,status)}

// 배정 전 확인: 예를 눌렀을 때만 저장하고, 선택 시 1시간 동안 확인창을 숨긴다.
const ASSIGNMENT_CONFIRM_SKIP_KEY='rr-assignment-confirm-skip-until';
function assignmentConfirmSkipped(){const until=Number(localStorage.getItem(ASSIGNMENT_CONFIRM_SKIP_KEY)||0);if(until>Date.now())return true;if(until)localStorage.removeItem(ASSIGNMENT_CONFIRM_SKIP_KEY);return false}
function applyAssignment(taskId,memberName,method='manual',score=0){const t=data.tasks.find(x=>x.id===taskId);const member=data.members.find(x=>x.name===memberName);if(!t||!member)return false;if(t.owner===memberName&&t.status==='assigned')return false;const old=t.owner;t.owner=memberName;t.status='assigned';const created=new Date(t.createdAt||today);const assignedDate=new Date(today);t.assignedAt=today;t.assignmentHours=Math.max(.5,Math.round(((assignedDate-created)/86400000||.5)*10)/10);data.history.push({id:Date.now()+Math.random(),taskId,taskTitle:t.title,previousOwner:old,newOwner:memberName,changedAt:today,method,score});return true}
function finishAssignment(taskId,memberName,method='manual',score=0){const changed=applyAssignment(taskId,memberName,method,score);if(!changed)return toast('이미 같은 담당자로 배정된 업무입니다.');syncComputedWorkloads();save();closeModal();toast(`${memberName}님에게 ${method==='auto'?'자동':'수동'} 배정했습니다.`);render()}
function openAssignmentConfirm(taskId,memberName,method='manual',score=0){const t=data.tasks.find(x=>x.id===taskId);const member=data.members.find(x=>x.name===memberName);if(!t||!member)return;if(assignmentConfirmSkipped())return finishAssignment(taskId,memberName,method,score);const candidate=recommend(t).find(x=>x.name===memberName)||{workload:workload(memberName),projectedWorkload:workload(memberName),score};$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal assign-confirm-modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><div class="confirm-hero"><span class="confirm-icon">✓</span><div><p class="eyebrow">ASSIGNMENT CHECK</p><h2>이 담당자로 배정할까요?</h2><p class="modal-help">예를 눌러야 업무 정보가 저장됩니다.</p></div></div><div class="assignment-review"><strong>${esc(t.title)}</strong><span>${method==='auto'?'자동 추천':'수동 선택'} · ${esc(memberName)}</span></div><div class="confirm-detail-grid"><div><label>담당자</label><strong>${esc(memberName)}</strong><small>${esc(member.level)} · 경력 ${member.experience||0}년</small></div><div><label>적합도</label><strong>${candidate.score||0}점</strong><small>직급·역량·경험 반영</small></div><div><label>현재 업무부하</label><strong>${candidate.workload||0}%</strong><small>배정 전 자동 계산</small></div><div><label>배정 후 예상 부하</label><strong>${candidate.projectedWorkload||0}%</strong><small class="${candidate.eligible===false?'warning':''}">${candidate.eligible===false?'허용 상한 초과':'부하 반영 완료'}</small></div></div><form id="assignmentConfirmForm" class="modal-form"><label class="confirm-skip"><input type="checkbox" name="skip"><span>1시간 동안 이 확인창 보지 않기</span></label><div class="modal-actions"><button type="button" class="btn secondary" onclick="closeModal()">취소</button><button type="submit" class="btn">예, 배정하기</button></div></form></section></div>`;$('#assignmentConfirmForm').onsubmit=e=>{e.preventDefault();const skip=Boolean(e.target.elements.skip.checked);if(skip)localStorage.setItem(ASSIGNMENT_CONFIRM_SKIP_KEY,String(Date.now()+3600000));finishAssignment(taskId,memberName,method,score)}}
function confirmAssignTask(id,name){const member=data.members.find(x=>x.name===name);if(!member)return toast('등록된 구성원을 찾을 수 없습니다.');const candidate=recommend(data.tasks.find(x=>x.id===id)).find(x=>x.name===name);openAssignmentConfirm(id,name,'manual',candidate?.score||0)}
function autoAssignTask(id){const t=data.tasks.find(x=>x.id===id);if(!t)return;const candidate=bestCandidate(t);if(!candidate)return toast('추천 가능한 구성원이 없습니다.');openAssignmentConfirm(id,candidate.name,'auto',candidate.score)}
function openAssignModal(id){const t=data.tasks.find(x=>x.id===id);if(!t)return;const candidates=recommend(t).slice(0,5);$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal assign-modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><p class="eyebrow">MANUAL ASSIGNMENT</p><h2>담당자 직접 선택</h2><p class="modal-help"><b>${esc(t.title)}</b> · 후보를 선택하면 배정 전 확인창이 열립니다.</p><div class="assign-candidates">${candidates.map((m,i)=>`<button class="assign-candidate ${m.eligible?'eligible':'overload'}" onclick="confirmAssignTask(${id},'${esc(m.name)}')"><span class="candidate-rank">${i+1}</span><span class="assign-person"><strong>${esc(m.name)}</strong><small>${esc(m.level)} · ${(m.skills||[]).slice(0,3).join(' · ')}</small></span><span class="assign-score"><b>${m.score}점</b><small>현재 ${m.workload}% · 배정 후 ${m.projectedWorkload}%</small></span><span class="assign-state">${m.eligible?'배정 가능':'상한 초과·확인 필요'}</span></button>`).join('')||'<div class="empty">추천 후보가 없습니다.</div>'}</div><div class="modal-actions"><button class="btn secondary" onclick="closeModal()">취소</button><button class="btn" onclick="autoAssignTask(${id})">1순위 자동 배정</button></div></section></div>`}
function assignTask(id){openAssignModal(id)}
function autoAssignAll(){const plans=data.tasks.filter(t=>t.status==='unassigned').map(t=>{const candidate=bestCandidate(t);return candidate?{task:t,candidate}:null}).filter(Boolean);if(!plans.length)return toast('미배정 업무가 없습니다.');if(assignmentConfirmSkipped()){plans.forEach(p=>applyAssignment(p.task.id,p.candidate.name,'auto-bulk',p.candidate.score));syncComputedWorkloads();save();toast(`${plans.length}건 자동 배정했습니다.`);render();return}$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal assign-confirm-modal bulk-confirm-modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><div class="confirm-hero"><span class="confirm-icon">✓</span><div><p class="eyebrow">BULK ASSIGNMENT CHECK</p><h2>${plans.length}건을 자동 배정할까요?</h2><p class="modal-help">예를 눌러야 일괄 배정됩니다.</p></div></div><div class="bulk-plan-list">${plans.slice(0,5).map(p=>`<div><strong>${esc(p.task.title)}</strong><span>${esc(p.candidate.name)} · 배정 후 ${p.candidate.projectedWorkload}%</span></div>`).join('')}${plans.length>5?`<small>외 ${plans.length-5}건 포함</small>`:''}</div><form id="bulkAssignmentConfirmForm" class="modal-form"><label class="confirm-skip"><input type="checkbox" name="skip"><span>1시간 동안 이 확인창 보지 않기</span></label><div class="modal-actions"><button type="button" class="btn secondary" onclick="closeModal()">취소</button><button type="submit" class="btn">예, 일괄 배정하기</button></div></form></section></div>`;$('#bulkAssignmentConfirmForm').onsubmit=e=>{e.preventDefault();if(e.target.elements.skip.checked)localStorage.setItem(ASSIGNMENT_CONFIRM_SKIP_KEY,String(Date.now()+3600000));plans.forEach(p=>applyAssignment(p.task.id,p.candidate.name,'auto-bulk',p.candidate.score));syncComputedWorkloads();save();closeModal();toast(`${plans.length}건 자동 배정했습니다.`);render()}}
function taskCard(t){const due=t.due?.slice(5).replace('-','.');const candidate=t.status==='unassigned'?bestCandidate(t):null;const feedback=canSubmitSatisfaction(t)?`<button class="satisfaction-btn" onclick="openSatisfaction(${t.id})">내 업무 만족도 남기기</button>`:`<span class="owner-only-note">만족도: 담당자 본인만 입력</span>`;const statusOptions=['unassigned','assigned','in_progress','blocked','done'].map(s=>`<option value="${s}" ${t.status===s?'selected':''} ${s==='unassigned'&&t.status!=='unassigned'&&!isAdminUser()?'disabled':''}>${statusLabel(s)}</option>`).join('');return `<article class="task-tile ${t.status}"><div class="task-head"><select class="status-select ${t.status}" aria-label="${esc(t.title)} 상태" onclick="event.stopPropagation()" onchange="quickStatusChange(${t.id},this.value)">${statusOptions}</select><span class="priority">${esc(t.taskType||'업무')} · ${esc(t.difficulty||'')} · ${t.estimatedHours||0}h</span></div><button class="task-title-button" onclick="openTaskDetail(${t.id})"><h3>${esc(t.title)}</h3></button><p class="task-meta">${esc(t.description)}</p><div class="task-tags">${(t.requiredSkills||[]).map(s=>`<span>역량 · ${esc(s)}</span>`).join('')}${(t.collaborators||[]).map(c=>`<span>협업 · ${esc(c)}</span>`).join('')}</div><div class="task-footer"><span class="owner-chip"><span class="mini-avatar">${t.owner==='미정'?'?':esc(t.owner[0])}</span>${esc(t.owner)}${t.owner!=='미정'?`<small>부하 ${workload(t.owner)}%</small>`:''}</span><span class="date">마감 ${due}</span></div>${t.status==='unassigned'?`<div class="recommend-box"><span>추천 후보 <b>${candidate?esc(candidate.name):'없음'}</b><small>${candidate?`적합도 ${candidate.score}점 · 배정 후 ${candidate.projectedWorkload}%`:''}</small></span><div class="assign-actions"><button class="auto-assign-btn" onclick="autoAssignTask(${t.id})">자동 배정</button><button class="manual-assign-btn" onclick="openAssignModal(${t.id})">수동 배정</button></div></div>`:feedback}</article>`}
function openTaskDetail(id){const t=data.tasks.find(x=>x.id===id);if(!t)return;const candidates=recommend(t).slice(0,3);$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal detail-modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><div class="detail-top"><div><span class="status ${t.status}">${statusLabel(t.status)}</span><p class="eyebrow">WORK ITEM DETAIL</p><h2>${esc(t.title)}</h2><p class="modal-help">${esc(t.description||'설명 없음')}</p></div><div class="detail-hours"><strong>${t.estimatedHours||0}h</strong><small>예상 소요</small></div></div><div class="detail-grid"><div><label>업무 종류</label><strong>${esc(t.taskType||'미지정')}</strong><small>업무 분류</small></div><div><label>난이도</label><strong>${esc(t.difficulty||t.requiredLevel||'미지정')}</strong><small>필요 직급 ${esc(t.requiredLevel||'미지정')}</small></div><div><label>담당자</label><strong>${esc(t.owner)}</strong><small>${t.owner==='미정'?'자동·수동 배정 대기':'현재 자동 계산 부하 '+workload(t.owner)+'%'}</small></div><div><label>기한</label><strong>${t.due||'미지정'}</strong><small>${t.due&&t.due<today?'기한 초과':'기한 내'}</small></div></div><div class="detail-section"><div class="detail-section-head"><label>추천 후보</label><small>업무 종류·역량·직급·경력·자동 부하 반영</small></div><div class="candidate-list">${candidates.map((m,i)=>`<div class="candidate-row"><span class="candidate-rank">${i+1}</span><div><strong>${esc(m.name)}</strong><small>${esc(m.level)} · ${(m.skills||[]).slice(0,3).join(' · ')}</small></div><b>${m.score}점</b><em>현재 ${m.workload}% · 배정 후 ${m.projectedWorkload}%</em></div>`).join('')||'<div class="empty">추천 후보 없음</div>'}</div></div><div class="detail-section"><label>상태 변경</label><div class="status-actions">${['unassigned','assigned','in_progress','blocked','done'].map(s=>`<button class="status-choice ${s===t.status?'selected':''}" onclick="changeTaskStatus(${id},'${s}')">${statusLabel(s)}</button>`).join('')}</div></div><div class="modal-actions"><button class="btn secondary" onclick="closeModal()">닫기</button>${t.status==='unassigned'?`<button class="btn secondary" onclick="openAssignModal(${id})">수동 배정</button><button class="btn" onclick="autoAssignTask(${id})">자동 배정</button>`:''}</div></section></div>`}

// 수상작 SaaS 대시보드에서 자주 쓰는 정보 위계: 핵심 숫자 → 추이 → 다음 행동 → 상세 큐.
// 다중 담당 확장: owner는 호환용 주담당, assignees가 실제 담당 팀이다.
function taskAssigneeNames(t){const raw=Array.isArray(t?.assignees)?t.assignees.filter(Boolean):[];if(!raw.length&&t?.owner&&t.owner!=='미정')raw.push(t.owner);return [...new Set(raw)].filter(name=>data.members.some(m=>m.name===name))}
function taskPrimaryName(t){return taskAssigneeNames(t)[0]||'미정'}
function isMultiTask(t){return t?.assignmentMode==='multi'||Number(t?.requiredAssignees)>1||taskAssigneeNames(t).length>1}
function taskAssigneeLabel(t){const names=taskAssigneeNames(t);return names.length>1?`${names[0]} 외 ${names.length-1}명`:names[0]||'미정'}
function calculatedWorkload(member){if(!member)return 0;const active=data.tasks.filter(t=>taskAssigneeNames(t).includes(member.name)&&!['done','unassigned'].includes(t.status));const weightedHours=active.reduce((sum,t)=>sum+taskLoadHours(t,member)/Math.max(taskAssigneeNames(t).length,1),0);const capacity=(Number(member.capacityHours)||24)*Math.max(.25,Math.min(1,Number(member.availability)||1));return Math.min(150,Math.round(weightedHours/capacity*100))}
function recommend(t,slots=Math.max(1,Number(t?.requiredAssignees)||1)){const required=(t?.requiredSkills||[]).filter(Boolean);return data.members.map(m=>{const current=calculatedWorkload(m);const typeMatch=(m.types||[]).includes(t.taskType)?30:0;const skillHits=required.filter(s=>(m.skills||[]).includes(s)).length;const skillScore=required.length?Math.round(skillHits/required.length*30):15;const levelScore=levelRank(m.level)>=levelRank(t.requiredLevel||t.difficulty)?20:5;const expScore=m.experience>=(t.minExperience||0)?10:Math.max(0,10-Math.round(((t.minExperience||0)-m.experience)*2));const capacityScore=Math.max(0,10-Math.round(current/10));const score=Math.max(0,Math.round(typeMatch+skillScore+levelScore+expScore+capacityScore));const projected=Math.round(current+(taskLoadHours(t,m)/Math.max(slots,1))/((Number(m.capacityHours)||24)*Math.max(.25,Number(m.availability)||1))*100);const eligible=current<(m.maxWorkload||85)&&projected<=(m.maxWorkload||85)&&levelRank(m.level)>=Math.max(0,levelRank(t.requiredLevel||'사원')-1);return {...m,workload:current,projectedWorkload:projected,score,eligible,breakdown:{type:typeMatch,skills:skillScore,level:levelScore,experience:expScore,capacity:capacityScore},skillHits}}).sort((a,b)=>(Number(b.eligible)-Number(a.eligible))||b.score-a.score)}
function recommendedTeam(t){const slots=isMultiTask(t)?Math.max(2,Number(t.requiredAssignees)||2):1;const candidates=recommend(t,slots);const eligible=candidates.filter(x=>x.eligible);return (eligible.length>=slots?eligible:candidates).slice(0,slots)}
function applyAssignment(taskId,memberNames,method='manual',score=0){const t=data.tasks.find(x=>x.id===taskId);const names=[...new Set((Array.isArray(memberNames)?memberNames:[memberNames]).filter(name=>data.members.some(m=>m.name===name)))];if(!t||!names.length)return false;const previous=taskAssigneeNames(t);if(previous.length===names.length&&previous.every((name,i)=>name===names[i])&&t.status!=='unassigned')return false;t.assignees=names;t.owner=names[0];t.assignmentMode=names.length>1?'multi':'single';t.assignedCount=names.length;if(!previous.length){const created=new Date(t.createdAt||today);const assignedDate=new Date(today);t.assignedAt=today;t.assignmentHours=Math.max(.5,Math.round(((assignedDate-created)/86400000||.5)*10)/10)}t.status=t.status==='unassigned'?'assigned':t.status;data.history.push({id:Date.now()+Math.random(),taskId,taskTitle:t.title,previousOwner:previous[0]||'미정',newOwner:names[0],previousOwners:previous,newOwners:names,assigneeNames:names,changedAt:today,method,score,memberCount:names.length});return true}
function finishAssignment(taskId,memberNames,method='manual',score=0){const names=Array.isArray(memberNames)?memberNames:[memberNames];const changed=applyAssignment(taskId,names,method,score);if(!changed)return toast('변경된 담당자가 없습니다.');syncComputedWorkloads();save();closeModal();toast(names.length>1?`${names[0]} 외 ${names.length-1}명에게 공동 배정했습니다.`:`${names[0]}님에게 ${method==='auto'?'자동':'수동'} 배정했습니다.`);render()}
function openAssignmentConfirm(taskId,memberName,method='manual',score=0){openAssignmentTeamConfirm(taskId,[memberName],method,score)}
function openAssignmentTeamConfirm(taskId,memberNames,method='manual',score=0){const t=data.tasks.find(x=>x.id===taskId);const names=[...new Set(memberNames||[])];if(!t||!names.length)return;if(assignmentConfirmSkipped())return finishAssignment(taskId,names,method,score);const candidates=recommend(t,names.length);const byName=new Map(candidates.map(x=>[x.name,x]));const previous=taskAssigneeNames(t);$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal assign-confirm-modal team-confirm-modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><div class="confirm-hero"><span class="confirm-icon">✓</span><div><p class="eyebrow">TEAM ASSIGNMENT CHECK</p><h2>${names.length>1?'공동 담당으로 배정할까요?':'이 담당자로 배정할까요?'}</h2><p class="modal-help">예를 눌러야 담당자 정보가 저장됩니다.</p></div></div><div class="assignment-review"><strong>${esc(t.title)}</strong><span>${method==='auto'?'자동 추천':'수동 선택'} · ${names.length}명 담당</span></div><div class="assignee-confirm-list">${names.map((name,i)=>{const c=byName.get(name)||{workload:workload(name),projectedWorkload:workload(name),score:0,eligible:true};return `<div class="assignee-confirm-row"><span class="mini-avatar">${esc(name[0])}</span><div><strong>${esc(name)}</strong><small>${i===0?'주담당':'공동담당'} · 현재 ${c.workload}% · 배정 후 ${c.projectedWorkload}%</small></div><b>${c.score}점</b></div>`}).join('')}</div>${previous.length?`<p class="previous-assignees">현재 담당: ${previous.map(esc).join(' · ')}</p>`:''}<form id="assignmentTeamConfirmForm" class="modal-form"><label class="confirm-skip"><input type="checkbox" name="skip"><span>1시간 동안 이 확인창 보지 않기</span></label><div class="modal-actions"><button type="button" class="btn secondary" onclick="closeModal()">취소</button><button type="submit" class="btn">예, 배정하기</button></div></form></section></div>`;$('#assignmentTeamConfirmForm').onsubmit=e=>{e.preventDefault();if(e.target.elements.skip.checked)localStorage.setItem(ASSIGNMENT_CONFIRM_SKIP_KEY,String(Date.now()+3600000));finishAssignment(taskId,names,method,score)}}
function confirmAssignTask(id,names){const selected=Array.isArray(names)?names:[names];const members=selected.filter(name=>data.members.some(m=>m.name===name));if(!members.length)return toast('담당자를 한 명 이상 선택해주세요.');const candidates=recommend(data.tasks.find(x=>x.id===id),members.length);openAssignmentTeamConfirm(id,members,'manual',candidates.find(x=>x.name===members[0])?.score||0)}
function autoAssignTask(id){const t=data.tasks.find(x=>x.id===id);if(!t)return;const team=recommendedTeam(t);if(!team.length)return toast('추천 가능한 구성원이 없습니다.');openAssignmentTeamConfirm(id,team.map(x=>x.name),'auto',team[0].score)}
function openAssignModal(id){const t=data.tasks.find(x=>x.id===id);if(!t)return;const selected=taskAssigneeNames(t);const slots=isMultiTask(t)?Math.max(2,Number(t.requiredAssignees)||2):1;const ranked=recommend(t,Math.max(slots,selected.length));const map=new Map([...selected.map(name=>[name,ranked.find(x=>x.name===name)||{name,level:data.members.find(m=>m.name===name)?.level||'',skills:data.members.find(m=>m.name===name)?.skills||[],workload:workload(name),projectedWorkload:workload(name),score:0,eligible:true}]),...ranked.map(x=>[x.name,x])]);const candidates=[...map.values()].slice(0,6);$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal assign-modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><p class="eyebrow">${selected.length?'TEAM ASSIGNMENT':'MANUAL ASSIGNMENT'}</p><h2>${selected.length?'담당자 조정':'담당자 직접 선택'}</h2><p class="modal-help"><b>${esc(t.title)}</b> · 여러 명을 선택하면 공동 담당으로 배정됩니다.</p><div class="assignment-mode-note"><strong>${isMultiTask(t)?`이 업무는 ${slots}명 공동 수행이 권장됩니다.`:'단독 담당 업무입니다.'}</strong><span>첫 번째 선택 인원이 주담당이 됩니다.</span></div><form id="manualAssignForm" class="modal-form"><div class="assign-candidates">${candidates.map((m,i)=>`<label class="assign-candidate ${m.eligible?'eligible':'overload'} ${selected.includes(m.name)?'selected':''}"><input type="checkbox" name="assigneeChoice" value="${esc(m.name)}" ${selected.includes(m.name)?'checked':''}><span class="candidate-rank">${i+1}</span><span class="assign-person"><strong>${esc(m.name)}</strong><small>${esc(m.level)} · ${(m.skills||[]).slice(0,3).join(' · ')}</small></span><span class="assign-score"><b>${m.score}점</b><small>현재 ${m.workload}% · 1인 배정 후 ${m.projectedWorkload}%</small></span><span class="assign-state">${m.eligible?'배정 가능':'상한 초과·확인 필요'}</span></label>`).join('')||'<div class="empty">추천 후보가 없습니다.</div>'}</div><div class="modal-actions"><button type="button" class="btn secondary" onclick="closeModal()">취소</button><button type="submit" class="btn">선택한 담당자 확인</button></div></form></section></div>`;$('#manualAssignForm').onsubmit=e=>{e.preventDefault();const names=[...new FormData(e.target).getAll('assigneeChoice')];if(!names.length)return toast('담당자를 한 명 이상 선택해주세요.');confirmAssignTask(id,names)}}
function assignTask(id){openAssignModal(id)}
function autoAssignAll(){const plans=data.tasks.filter(t=>t.status==='unassigned').map(t=>{const team=recommendedTeam(t);return team.length?{task:t,team}:null}).filter(Boolean);if(!plans.length)return toast('미배정 업무가 없습니다.');if(assignmentConfirmSkipped()){plans.forEach(p=>applyAssignment(p.task.id,p.team.map(x=>x.name),'auto-bulk',p.team[0].score));syncComputedWorkloads();save();toast(`${plans.length}건 자동 배정했습니다.`);render();return}$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal assign-confirm-modal bulk-confirm-modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><div class="confirm-hero"><span class="confirm-icon">✓</span><div><p class="eyebrow">BULK TEAM ASSIGNMENT</p><h2>${plans.length}건을 자동 배정할까요?</h2><p class="modal-help">공동 수행 업무는 추천 인원을 함께 배정합니다.</p></div></div><div class="bulk-plan-list">${plans.slice(0,5).map(p=>`<div><strong>${esc(p.task.title)}</strong><span>${p.team.map(x=>esc(x.name)).join(' · ')}</span></div>`).join('')}${plans.length>5?`<small>외 ${plans.length-5}건 포함</small>`:''}</div><form id="bulkAssignmentConfirmForm" class="modal-form"><label class="confirm-skip"><input type="checkbox" name="skip"><span>1시간 동안 이 확인창 보지 않기</span></label><div class="modal-actions"><button type="button" class="btn secondary" onclick="closeModal()">취소</button><button type="submit" class="btn">예, 일괄 배정하기</button></div></form></section></div>`;$('#bulkAssignmentConfirmForm').onsubmit=e=>{e.preventDefault();if(e.target.elements.skip.checked)localStorage.setItem(ASSIGNMENT_CONFIRM_SKIP_KEY,String(Date.now()+3600000));plans.forEach(p=>applyAssignment(p.task.id,p.team.map(x=>x.name),'auto-bulk',p.team[0].score));syncComputedWorkloads();save();closeModal();toast(`${plans.length}건 자동 배정했습니다.`);render()}}
function openTaskForm(){const root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal task-modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><p class="eyebrow">NEW WORK ITEM</p><h2>업무 등록</h2><p class="modal-help">업무 조건과 예상 협업 인원을 설정하면 자동 배정이 팀 단위로 계산됩니다.</p><form id="taskModalForm" class="modal-form"><div class="form-grid"><div class="field full-field"><label>업무명 <em>*</em></label><input name="title" required placeholder="예: 리더십다면진단 운영"></div><div class="field full-field"><label>업무 설명</label><textarea name="description" placeholder="업무 목적과 주요 결과물을 적어주세요."></textarea></div><div class="field"><label>업무 종류</label><select name="taskType">${TASK_TYPES.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>업무 난이도</label><select name="difficulty">${TASK_LEVELS.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>필요 최소 직급</label><select name="level">${TASK_LEVELS.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>최소 경험(년)</label><input name="experience" type="number" min="0" value="3"></div><div class="field"><label>배정 방식</label><select name="assignmentMode" id="assignmentMode"><option value="single">단독 담당</option><option value="multi">다중 협업</option></select></div><div class="field" id="assigneeCountField" style="display:none"><label>필요 담당 인원</label><select name="requiredAssignees"><option>2</option><option>3</option><option>4</option></select></div><div class="field full-field"><label>필요 역량</label><div class="check-grid">${SKILL_LIBRARY.map(x=>`<label class="check-chip"><input type="checkbox" name="skills" value="${x}"><span>${x}</span></label>`).join('')}</div></div><div class="field"><label>예상 소요시간</label><input name="hours" type="number" min="1" value="8"></div><div class="field"><label>기한</label><input name="due" type="date" value="${today}" required></div><div class="field full-field"><label>협업 부서</label><input name="collaborators" placeholder="쉼표로 구분"></div></div><div class="modal-actions"><button type="button" class="btn secondary" onclick="closeModal()">취소</button><button class="btn" type="submit">업무 등록</button></div></form></section></div>`;$('#assignmentMode').onchange=e=>{$('#assigneeCountField').style.display=e.target.value==='multi'?'block':'none'};$('#taskModalForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const title=String(f.get('title')).trim();if(!title)return;const mode=String(f.get('assignmentMode'));data.tasks.push({id:Date.now(),title,description:String(f.get('description')||''),owner:'미정',assignees:[],assignmentMode:mode,requiredAssignees:mode==='multi'?Number(f.get('requiredAssignees'))||2:1,due:String(f.get('due')),status:'unassigned',createdBy:data.members[0].name,createdAt:today,taskType:String(f.get('taskType')),difficulty:String(f.get('difficulty')),requiredLevel:String(f.get('level')),requiredSkills:f.getAll('skills'),minExperience:Number(f.get('experience'))||0,estimatedHours:Number(f.get('hours'))||8,collaborators:String(f.get('collaborators')||'').split(',').map(x=>x.trim()).filter(Boolean)});save();closeModal();toast(mode==='multi'?'공동 수행 업무를 등록했습니다.':'업무를 등록했습니다.');render()}}
function taskCard(t){const due=t.due?.slice(5).replace('-','.');const names=taskAssigneeNames(t);const candidate=t.status==='unassigned'?recommendedTeam(t)[0]:null;const feedback=canSubmitSatisfaction(t)?`<button class="satisfaction-btn" onclick="openSatisfaction(${t.id})">내 업무 만족도 남기기</button>`:`<span class="owner-only-note">담당자 본인만 만족도 입력</span>`;const statusOptions=['unassigned','assigned','in_progress','blocked','done'].map(s=>`<option value="${s}" ${t.status===s?'selected':''} ${s==='unassigned'&&t.status!=='unassigned'&&!isAdminUser()?'disabled':''}>${statusLabel(s)}</option>`).join('');const avatars=names.slice(0,3).map(name=>`<i>${esc(name[0])}</i>`).join('');const assignmentLabel=names.length?taskAssigneeLabel(t):'담당자 미정';return `<article class="task-tile ${t.status}"><div class="task-head"><select class="status-select ${t.status}" aria-label="${esc(t.title)} 상태" onclick="event.stopPropagation()" onchange="quickStatusChange(${t.id},this.value)">${statusOptions}</select><span class="priority">${esc(t.taskType||'업무')} · ${esc(t.difficulty||'')} · ${t.estimatedHours||0}h${names.length>1?' · '+names.length+'명':''}</span></div><button class="task-title-button" onclick="openTaskDetail(${t.id})"><h3>${esc(t.title)}</h3></button><p class="task-meta">${esc(t.description)}</p><div class="task-tags">${(t.requiredSkills||[]).map(s=>`<span>역량 · ${esc(s)}</span>`).join('')}${(t.collaborators||[]).map(c=>`<span>협업 · ${esc(c)}</span>`).join('')}</div><div class="task-footer"><span class="owner-chip"><span class="avatar-stack">${avatars||'<i>?</i>'}</span><span>${esc(assignmentLabel)}${names.length>1?'<small>공동 담당</small>':names.length?`<small>부하 ${workload(names[0])}%</small>`:''}</span></span><span class="date">마감 ${due}</span></div>${t.status==='unassigned'?`<div class="recommend-box"><span>추천 팀 <b>${recommendedTeam(t).map(x=>esc(x.name)).join(' · ')||'없음'}</b><small>${candidate?`대표 적합도 ${candidate.score}점 · ${candidate.projectedWorkload}%`:''}</small></span><div class="assign-actions"><button class="auto-assign-btn" onclick="autoAssignTask(${t.id})">자동 배정</button><button class="manual-assign-btn" onclick="openAssignModal(${t.id})">수동 배정</button></div></div>`:`<div class="task-bottom-actions"><div>${feedback}</div><button class="manual-assign-btn" onclick="openAssignModal(${t.id})">담당자 조정</button></div>`}</article>`}
function openTaskDetail(id){const t=data.tasks.find(x=>x.id===id);if(!t)return;const names=taskAssigneeNames(t);const candidates=recommend(t,Math.max(1,names.length||Number(t.requiredAssignees)||1)).slice(0,3);$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal detail-modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><div class="detail-top"><div><span class="status ${t.status}">${statusLabel(t.status)}</span><p class="eyebrow">WORK ITEM DETAIL</p><h2>${esc(t.title)}</h2><p class="modal-help">${esc(t.description||'설명 없음')}</p></div><div class="detail-hours"><strong>${t.estimatedHours||0}h</strong><small>${names.length>1?'공동 예상 소요':'예상 소요'}</small></div></div><div class="detail-grid"><div><label>업무 종류</label><strong>${esc(t.taskType||'미지정')}</strong><small>업무 분류</small></div><div><label>난이도</label><strong>${esc(t.difficulty||t.requiredLevel||'미지정')}</strong><small>필요 직급 ${esc(t.requiredLevel||'미지정')}</small></div><div><label>담당 팀</label><strong>${esc(names.length?names.join(' · '):'미정')}</strong><small>${names.length>1?'주담당 1명 · 공동담당 '+(names.length-1)+'명':names.length?'현재 자동 계산 부하 '+workload(names[0])+'%':'자동·수동 배정 대기'}</small></div><div><label>기한</label><strong>${t.due||'미지정'}</strong><small>${t.due&&t.due<today?'기한 초과':'기한 내'}</small></div></div><div class="detail-section"><div class="detail-section-head"><label>추천 후보</label><small>업무 종류·역량·직급·경력·부하 반영</small></div><div class="candidate-list">${candidates.map((m,i)=>`<div class="candidate-row"><span class="candidate-rank">${i+1}</span><div><strong>${esc(m.name)}</strong><small>${esc(m.level)} · ${(m.skills||[]).slice(0,3).join(' · ')}</small></div><b>${m.score}점</b><em>현재 ${m.workload}% · 1인 배정 후 ${m.projectedWorkload}%</em></div>`).join('')||'<div class="empty">추천 후보 없음</div>'}</div></div><div class="detail-section"><label>상태 변경</label><div class="status-actions">${['unassigned','assigned','in_progress','blocked','done'].map(s=>`<button class="status-choice ${s===t.status?'selected':''}" onclick="changeTaskStatus(${id},'${s}')">${statusLabel(s)}</button>`).join('')}</div></div><div class="modal-actions"><button class="btn secondary" onclick="closeModal()">닫기</button><button class="btn secondary" onclick="openAssignModal(${id})">${names.length?'담당자 조정':'수동 배정'}</button>${t.status==='unassigned'?`<button class="btn" onclick="autoAssignTask(${id})">자동 배정</button>`:''}</div></section></div>`}
function filteredTasks(){return data.tasks.filter(t=>(!taskQuery||`${t.title} ${t.description} ${(t.collaborators||[]).join(' ')} ${taskAssigneeNames(t).join(' ')}`.toLowerCase().includes(taskQuery.toLowerCase()))&&(taskStatus==='all'||t.status===taskStatus)&&(taskOwner==='all'||taskAssigneeNames(t).includes(taskOwner))).sort((a,b)=>taskSort==='owner'?taskAssigneeLabel(a).localeCompare(taskAssigneeLabel(b)):taskSort==='new'?b.id-a.id:(a.due||'9999').localeCompare(b.due||'9999'))}
function canSubmitSatisfaction(t){return !!t&&taskAssigneeNames(t).includes(currentUserName())}
function taskEditButton(id){return isAdminUser()?`<button class="task-edit-btn" onclick="event.stopPropagation();openTaskEdit(${id})">편집</button>`:''}
function openTaskEdit(id){const t=data.tasks.find(x=>x.id===id);if(!t)return;if(!isAdminUser())return toast('팀장만 업무 항목을 수정할 수 있습니다.');const currentNames=taskAssigneeNames(t);const mode=isMultiTask(t)?'multi':(t.assignmentMode||'single');const required=Math.max(2,Number(t.requiredAssignees)||2);$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal task-modal edit-task-modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><p class="eyebrow">EDIT WORK ITEM</p><h2>업무 항목 수정</h2><p class="modal-help">팀장 전용 · 현재 담당자${currentNames.length?' '+currentNames.join(' · '):' 미정'}는 유지되고, 수정된 조건은 다음 배정 추천에 반영됩니다.</p><form id="taskEditForm" class="modal-form"><div class="form-grid"><div class="field full-field"><label>업무명 <em>*</em></label><input name="title" required value="${esc(t.title)}"></div><div class="field full-field"><label>업무 설명</label><textarea name="description">${esc(t.description||'')}</textarea></div><div class="field"><label>업무 종류</label><select name="taskType">${TASK_TYPES.map(x=>`<option ${t.taskType===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>업무 난이도</label><select name="difficulty">${TASK_LEVELS.map(x=>`<option ${t.difficulty===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>필요 최소 직급</label><select name="level">${TASK_LEVELS.map(x=>`<option ${t.requiredLevel===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>최소 경험(년)</label><input name="experience" type="number" min="0" value="${Number(t.minExperience)||0}"></div><div class="field"><label>배정 방식</label><select name="assignmentMode" id="editAssignmentMode"><option value="single" ${mode==='single'?'selected':''}>단독 담당</option><option value="multi" ${mode==='multi'?'selected':''}>다중 협업</option></select></div><div class="field" id="editAssigneeCountField" style="display:${mode==='multi'?'block':'none'}"><label>필요 담당 인원</label><select name="requiredAssignees">${[2,3,4].map(n=>`<option value="${n}" ${required===n?'selected':''}>${n}명</option>`).join('')}</select></div><div class="field full-field"><label>필요 역량</label><div class="check-grid">${SKILL_LIBRARY.map(x=>`<label class="check-chip"><input type="checkbox" name="skills" value="${x}" ${(t.requiredSkills||[]).includes(x)?'checked':''}><span>${x}</span></label>`).join('')}</div></div><div class="field"><label>예상 소요시간</label><input name="hours" type="number" min="1" value="${Number(t.estimatedHours)||8}"></div><div class="field"><label>기한</label><input name="due" type="date" value="${t.due||today}" required></div><div class="field full-field"><label>협업 부서</label><input name="collaborators" value="${esc((t.collaborators||[]).join(', '))}" placeholder="쉼표로 구분"></div><div class="field full-field"><label>수정 사유</label><textarea name="editReason" required placeholder="예: 업무 범위 변경, 담당 부서 협의 결과 반영"></textarea></div></div><div class="modal-actions"><button type="button" class="btn secondary" onclick="closeModal()">취소</button><button class="btn" type="submit">수정 저장</button></div></form></section></div>`;$('#editAssignmentMode').onchange=e=>{$('#editAssigneeCountField').style.display=e.target.value==='multi'?'block':'none'};$('#taskEditForm').onsubmit=e=>{e.preventDefault();if(!isAdminUser())return toast('팀장만 업무 항목을 수정할 수 있습니다.');const f=new FormData(e.target);const reason=String(f.get('editReason')||'').trim();if(!reason)return toast('수정 사유를 입력해주세요.');const before={title:t.title,description:t.description,taskType:t.taskType,difficulty:t.difficulty,requiredLevel:t.requiredLevel,minExperience:t.minExperience,requiredSkills:[...(t.requiredSkills||[])],estimatedHours:t.estimatedHours,due:t.due,collaborators:[...(t.collaborators||[])],assignmentMode:t.assignmentMode||'single',requiredAssignees:t.requiredAssignees||1};const nextMode=String(f.get('assignmentMode'));const nextCount=nextMode==='multi'?Number(f.get('requiredAssignees'))||2:1;t.title=String(f.get('title')).trim();t.description=String(f.get('description')||'');t.taskType=String(f.get('taskType'));t.difficulty=String(f.get('difficulty'));t.requiredLevel=String(f.get('level'));t.minExperience=Number(f.get('experience'))||0;t.requiredSkills=f.getAll('skills');t.estimatedHours=Number(f.get('hours'))||8;t.due=String(f.get('due'));t.collaborators=String(f.get('collaborators')||'').split(',').map(x=>x.trim()).filter(Boolean);t.assignmentMode=currentNames.length>1?'multi':nextMode;t.requiredAssignees=currentNames.length>1?Math.max(currentNames.length,nextCount):nextCount;const after={title:t.title,description:t.description,taskType:t.taskType,difficulty:t.difficulty,requiredLevel:t.requiredLevel,minExperience:t.minExperience,requiredSkills:[...t.requiredSkills],estimatedHours:t.estimatedHours,due:t.due,collaborators:[...t.collaborators],assignmentMode:t.assignmentMode,requiredAssignees:t.requiredAssignees};const changedFields=Object.keys(after).filter(key=>JSON.stringify(before[key])!==JSON.stringify(after[key]));if(!changedFields.length){closeModal();return toast('변경된 내용이 없습니다.')}data.history.push({id:Date.now()+Math.random(),kind:'task_edit',taskId:id,taskTitle:t.title,changedFields,previousValues:before,newValues:after,reason,changedBy:currentUserName(),changedAt:today});syncComputedWorkloads();save();closeModal();toast('업무 항목을 수정했습니다.');render()}}
function taskCard(t){const due=t.due?.slice(5).replace('-','.');const names=taskAssigneeNames(t);const candidate=t.status==='unassigned'?recommendedTeam(t)[0]:null;const feedback=canSubmitSatisfaction(t)?`<button class="satisfaction-btn" onclick="openSatisfaction(${t.id})">내 업무 만족도 남기기</button>`:`<span class="owner-only-note">담당자 본인만 만족도 입력</span>`;const statusOptions=['unassigned','assigned','in_progress','blocked','done'].map(s=>`<option value="${s}" ${t.status===s?'selected':''} ${s==='unassigned'&&t.status!=='unassigned'&&!isAdminUser()?'disabled':''}>${statusLabel(s)}</option>`).join('');const avatars=names.slice(0,3).map(name=>`<i>${esc(name[0])}</i>`).join('');const assignmentLabel=names.length?taskAssigneeLabel(t):'담당자 미정';return `<article class="task-tile ${t.status}"><div class="task-head"><select class="status-select ${t.status}" aria-label="${esc(t.title)} 상태" onclick="event.stopPropagation()" onchange="quickStatusChange(${t.id},this.value)">${statusOptions}</select><span class="priority">${esc(t.taskType||'업무')} · ${esc(t.difficulty||'')} · ${t.estimatedHours||0}h${names.length>1?' · '+names.length+'명':''}</span>${taskEditButton(t.id)}</div><button class="task-title-button" onclick="openTaskDetail(${t.id})"><h3>${esc(t.title)}</h3></button><p class="task-meta">${esc(t.description)}</p><div class="task-tags">${(t.requiredSkills||[]).map(s=>`<span>역량 · ${esc(s)}</span>`).join('')}${(t.collaborators||[]).map(c=>`<span>협업 · ${esc(c)}</span>`).join('')}</div><div class="task-footer"><span class="owner-chip"><span class="avatar-stack">${avatars||'<i>?</i>'}</span><span>${esc(assignmentLabel)}${names.length>1?'<small>공동 담당</small>':names.length?`<small>부하 ${workload(names[0])}%</small>`:''}</span></span><span class="date">마감 ${due}</span></div>${t.status==='unassigned'?`<div class="recommend-box"><span>추천 팀 <b>${recommendedTeam(t).map(x=>esc(x.name)).join(' · ')||'없음'}</b><small>${candidate?`대표 적합도 ${candidate.score}점 · ${candidate.projectedWorkload}%`:''}</small></span><div class="assign-actions"><button class="auto-assign-btn" onclick="autoAssignTask(${t.id})">자동 배정</button><button class="manual-assign-btn" onclick="openAssignModal(${t.id})">수동 배정</button></div></div>`:`<div class="task-bottom-actions"><div>${feedback}</div><button class="manual-assign-btn" onclick="openAssignModal(${t.id})">담당자 조정</button></div>`}</article>`}
function admin(){const assigned=data.tasks.filter(t=>taskAssigneeNames(t).length).length;return `<section class="view">${heading('관리자','CONTROL ROOM','지표 입력 현황, 업무 배정, 변경 이력을 확인하고 관리합니다.','<button class="btn secondary" onclick="downloadCSV()">CSV 다운로드</button>')}<div class="metric-grid"><div class="metric-card"><div class="metric-top"><span>이번 주 입력</span></div><div class="metric-value">${data.entries.length+data.notes.length}<em>건</em></div><div class="metric-note">정량 ${data.entries.length} · 정성 ${data.notes.length}</div></div><div class="metric-card"><div class="metric-top"><span>미배정 업무</span></div><div class="metric-value">${data.tasks.length-assigned}<em>건</em></div><div class="metric-note">모든 업무에 담당 팀을 연결하세요</div></div><div class="metric-card"><div class="metric-top"><span>담당 변경 이력</span></div><div class="metric-value">${data.history.length}<em>건</em></div><div class="metric-note">주담당·공동담당 변경을 함께 보관</div></div></div><div class="panel"><div class="panel-header"><div><div class="panel-title">업무 배정 관리</div><div class="panel-desc">공동 수행 업무는 담당 팀 전체와 배정 후 부하를 확인합니다.</div></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>항목</th><th>상태</th><th>담당 팀</th><th>부하율</th><th>기한</th><th>관리</th></tr></thead><tbody>${data.tasks.map(t=>`<tr><td><strong>${esc(t.title)}</strong></td><td><span class="status ${t.status}">${statusLabel(t.status)}</span></td><td>${esc(taskAssigneeLabel(t))}${taskAssigneeNames(t).length>1?`<small class="table-subtext">${taskAssigneeNames(t).length}명 공동</small>`:''}</td><td>${taskAssigneeNames(t).length?taskAssigneeNames(t).map(n=>`${esc(n)} ${workload(n)}%`).join('<br>'):'—'}</td><td>${t.due||'—'}</td><td class="actions"><button class="text-btn" onclick="assignTask(${t.id})">${taskAssigneeNames(t).length?'담당자 조정':'수동 배정'}</button><button class="text-btn danger" onclick="removeTask(${t.id})">삭제</button></td></tr>`).join('')}</tbody></table></div></div><div class="panel history-panel"><div class="panel-title">최근 담당 변경 이력</div>${data.history.slice(-5).reverse().map(h=>`<p class="history-row"><b>${esc(h.taskTitle)}</b><span>${esc((h.previousOwners||[h.previousOwner||'미정']).join(' · '))} → ${esc((h.newOwners||[h.newOwner?[h.newOwner]:'']).join(' · '))}</span><small>${h.changedAt}</small></p>`).join('')||'<div class="empty">변경 이력이 없습니다.</div>'}</div></section>`}
function team(){return `<section class="view">${heading('팀원 프로필','TEAM DIRECTORY','구성원별 역량·경력·업무부하·담당 영역을 확인합니다.','<button class="btn secondary" onclick="openProfile()">내 프로필</button>')}<div class="team-summary"><div><strong>${data.members.length}</strong><span>전체 구성원</span></div><div><strong>${Math.round(data.members.reduce((a,m)=>a+calculatedWorkload(m),0)/data.members.length)}%</strong><span>평균 업무부하</span></div><div><strong>${data.members.filter(m=>calculatedWorkload(m)>=80).length}</strong><span>부하 주의</span></div></div><div class="member-grid">${data.members.map(m=>{const owned=data.tasks.filter(t=>taskAssigneeNames(t).includes(m.name));const load=calculatedWorkload(m);const tone=load>=80?'high':load>=60?'mid':'ok';return `<article class="member-card"><div class="member-top"><span class="profile-avatar small">${esc(m.name[0])}</span><div><h3>${esc(m.name)}</h3><p>${esc(m.level)} · 경력 ${m.experience}년</p></div><span class="member-status ${tone}">${load>=80?'주의':load>=60?'집중':'여유'}</span></div><div class="member-load"><div><span>자동 계산 업무부하</span><strong>${load}%</strong></div><div class="load-bar"><span class="${tone}" style="width:${Math.min(load,100)}%"></span></div></div><div class="member-capability"><label>가능 업무</label><span>${(m.types||[]).join(' · ')||'미설정'}</span></div><div class="chip-list">${m.skills.map(s=>`<span>${esc(s)}</span>`).join('')||'<span>역량 미설정</span>'}</div><div class="member-footer"><span>담당 업무 <b>${owned.length}건</b></span><button class="text-btn" onclick="openMemberProfile('${esc(m.name)}')">상세 보기 →</button></div></article>`}).join('')}</div></section>`}
function openMemberProfile(name){const m=data.members.find(x=>x.name===name);if(!m)return;const owned=data.tasks.filter(t=>taskAssigneeNames(t).includes(name));$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal profile-modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><div class="profile-hero"><span class="profile-avatar">${esc(m.name[0])}</span><div><p class="eyebrow">TEAM MEMBER</p><h2>${esc(m.name)}</h2><p>${esc(m.level)} · ${m.experience}년 경력</p></div></div><div class="profile-grid"><div class="profile-block"><label>현재 자동 계산 업무부하</label><div class="profile-load"><strong>${calculatedWorkload(m)}%</strong><div class="load-bar"><span class="${calculatedWorkload(m)>=80?'high':calculatedWorkload(m)>=60?'mid':'ok'}" style="width:${Math.min(calculatedWorkload(m),100)}%"></span></div></div></div><div class="profile-block"><label>담당 업무</label><strong>${owned.length}건</strong><small>${owned.map(t=>esc(t.title)).join(' · ')||'현재 담당 업무 없음'}</small></div></div><div class="member-task-list"><label>담당 업무 목록</label>${owned.map(t=>`<button onclick="openTaskDetail(${t.id})"><span class="status ${t.status}">${statusLabel(t.status)}</span><b>${esc(t.title)}</b><small>${taskAssigneeNames(t).length>1?'공동 담당 · ':''}${t.due||'기한 미지정'}</small></button>`).join('')||'<div class="empty">담당 업무 없음</div>'}</div></section></div>`}
function dashboard(){const total=data.tasks.length||1;const assigned=data.tasks.filter(t=>t.status!=='unassigned'&&t.owner!=='미정').length;const pending=data.tasks.filter(t=>t.status==='unassigned').length;const active=data.tasks.filter(t=>['assigned','in_progress','blocked'].includes(t.status)).length;const done=data.tasks.filter(t=>t.status==='done').length;const rate=Math.round(assigned/total*100)||0;const completion=Math.round(done/total*100)||0;const queue=[...data.tasks].sort((a,b)=>(a.status==='unassigned'?0:1)-(b.status==='unassigned'?0:1)||(a.due||'9999').localeCompare(b.due||'9999')).slice(0,4);const urgent=data.tasks.filter(t=>t.status==='blocked'||t.status==='unassigned'||(t.due&&t.due<='2026-08-21')).slice(0,3);return `<section class="view dashboard-view"><div class="dashboard-hero"><div><div class="hero-kicker"><span class="hero-live-dot"></span> WEEKLY OPERATIONS · ${data.members.length}명 참여 중</div><h1>업무의 빈틈을 찾고,<br><em>다음 담당까지 연결합니다.</em></h1><p>모호한 R&R을 한 화면에서 확인하고, 적합한 담당자와 기한을 바로 결정하세요.</p></div><div class="hero-actions"><button class="btn" onclick="go('tasks');setTimeout(openTaskForm,0)">+ 업무 올리기</button><button class="btn secondary" onclick="go('records')">KPI 확인</button><div class="hero-updated"><span>LAST SYNC</span><b>${today.replaceAll('-','.')}</b></div></div></div><div class="dashboard-kpis"><article class="dashboard-kpi featured"><div class="kpi-label"><span>담당 배정 완료율</span><b>목표 80%</b></div><div class="kpi-number">${rate}<em>%</em></div><div class="kpi-bottom"><span>${pending?`미배정 ${pending}건 확인 필요`:'모든 업무 담당 지정 완료'}</span><span class="kpi-trend ${rate>=80?'positive':'warning'}">${rate>=80?'↗ 목표 달성':'↗ '+(80-rate)+'%p 남음'}</span></div><div class="kpi-progress"><i style="width:${Math.min(rate,100)}%"></i></div></article><article class="dashboard-kpi"><div class="kpi-label"><span>진행 중 업무</span><b>ACTIVE QUEUE</b></div><div class="kpi-number">${active}<em>건</em></div><div class="kpi-bottom"><span>완료 ${done}건 · 달성률 ${completion}%</span><span class="kpi-icon">↗</span></div></article><article class="dashboard-kpi"><div class="kpi-label"><span>배정까지 평균 시간</span><b>최근 30일</b></div><div class="kpi-number">2.4<em>일</em></div><div class="kpi-bottom"><span>기준선 대비 0.8일 단축</span><span class="kpi-trend positive">↘ -25%</span></div></article></div><div class="dashboard-insight-grid"><article class="panel performance-panel"><div class="panel-header"><div><div class="panel-title">담당 배정 추이</div><div class="panel-desc">주간 흐름과 목표선 대비 현재 위치</div></div><span class="panel-pill"><i></i> LIVE DATA</span></div><div class="performance-summary"><strong>${rate}%</strong><span>현재 배정률</span><small>목표선 80%</small></div><div class="performance-chart"><div class="chart-lines"><i></i><i></i><i></i><i></i></div><svg viewBox="0 0 640 170" preserveAspectRatio="none"><path d="M0 137 C75 130 110 119 174 124 S258 100 316 108 S385 76 443 84 S548 49 640 54 L640 170 L0 170Z" fill="#0f4c81" fill-opacity=".11"/><path d="M0 137 C75 130 110 119 174 124 S258 100 316 108 S385 76 443 84 S548 49 640 54" fill="none" stroke="#0f4c81" stroke-width="3"/><circle cx="640" cy="54" r="5" fill="#f4bd68"/></svg><div class="chart-axis"><span>7/20</span><span>7/27</span><span>8/03</span><span>8/10</span><span>이번 주</span></div></div></article><article class="panel mission-panel"><div class="panel-header"><div><div class="panel-title">이번 주 운영 신호</div><div class="panel-desc">관리자가 먼저 확인할 상태</div></div><span class="signal-badge ${pending?'attention':'stable'}">${pending?'ATTENTION':'STABLE'}</span></div><div class="mission-ring" style="--ring:${Math.min(rate,100)*3.6}deg"><div><strong>${rate}</strong><span>% 배정</span></div></div><div class="mission-caption"><strong>${pending?'배정이 필요한 업무가 있습니다.':'이번 주 흐름이 안정적입니다.'}</strong><span>${pending?'추천 후보를 검토해 바로 배정하세요.':'현재 업무 상태를 유지하며 진행하세요.'}</span></div><div class="mission-stats"><div><b>${pending}</b><span>미배정</span></div><div><b>${active}</b><span>진행 중</span></div><div><b>${done}</b><span>완료</span></div></div></article></div><div class="dashboard-lower-grid"><article class="panel work-stream-panel"><div class="panel-header"><div><div class="panel-title">업무 큐</div><div class="panel-desc">지금 처리해야 할 우선순위</div></div><button class="text-btn" onclick="go('tasks')">전체 업무 →</button></div><div class="work-stream-list">${queue.map(t=>`<button class="work-stream-row" onclick="openTaskDetail(${t.id})"><span class="stream-status ${t.status}">${statusLabel(t.status)}</span><span class="stream-main"><strong>${esc(t.title)}</strong><small>${esc(t.taskType||'업무')} · ${t.owner==='미정'?'담당자 미정':esc(t.owner)}</small></span><span class="stream-due">${t.due?.slice(5).replace('-','.')||'기한 없음'} <b>›</b></span></button>`).join('')||'<div class="empty">등록된 업무가 없습니다.</div>'}</div></article><article class="panel role-panel"><div class="panel-header"><div><div class="panel-title">역할과 부하</div><div class="panel-desc">자동 배정에 반영되는 현재 상태</div></div><button class="text-btn" onclick="go('team')">팀원 보기 →</button></div><div class="role-list">${data.members.slice(0,5).map(m=>{const load=calculatedWorkload(m);const color=load>=80?'high':load>=60?'mid':'ok';return `<div class="role-row"><span class="owner-avatar">${esc(m.name[0])}</span><span class="role-person"><strong>${esc(m.name)}</strong><small>${esc(m.level)} · ${m.skills.slice(0,2).join(' · ')}</small></span><span class="role-load"><i class="load-bar"><b class="${color}" style="width:${Math.min(load,100)}%"></b></i><strong>${load}%</strong></span></div>`}).join('')}</div></article></div>${urgent.length?`<div class="attention-strip"><div><span class="attention-kicker">NEEDS ATTENTION</span><strong>지금 확인할 업무</strong><small>막힘·미배정·기한 임박 항목</small></div><div class="attention-strip-list">${urgent.map(t=>`<button onclick="openTaskDetail(${t.id})"><span class="attention-dot ${t.status}"></span><b>${esc(t.title)}</b><small>${t.status==='unassigned'?'담당자 미정':t.status==='blocked'?'막힘':'마감 '+t.due}</small><em>›</em></button>`).join('')}</div></div>`:''}</section>`}
function dashboardExtras(){const pending=data.tasks.filter(t=>t.status==='unassigned').length;const assigned=data.tasks.filter(t=>t.status==='assigned').length;const active=data.tasks.filter(t=>['in_progress','blocked'].includes(t.status)).length;const done=data.tasks.filter(t=>t.status==='done').length;return `<div class="dashboard-command-grid"><div class="workflow-panel command-panel"><div class="workflow-head"><div><p class="eyebrow">NEXT ACTION</p><h2>이번 주 업무 흐름</h2><p>상태를 클릭하면 해당 업무 목록으로 바로 이동합니다.</p></div><div class="workflow-actions"><button class="btn secondary" onclick="go('tasks');taskStatus='unassigned';render()">미배정 확인</button>${pending?`<button class="btn" onclick="autoAssignAll()">${pending}건 자동 배정</button>`:''}</div></div><div class="workflow-steps"><button onclick="go('tasks');taskStatus='unassigned';render()" class="workflow-step ${pending?'attention':''}"><span>01</span><b>담당자 대기</b><strong>${pending}</strong><small>미배정 업무</small></button><button onclick="go('tasks');taskStatus='assigned';render()" class="workflow-step"><span>02</span><b>업무 시작 전</b><strong>${assigned}</strong><small>배정 완료</small></button><button onclick="go('tasks');taskStatus='in_progress';render()" class="workflow-step"><span>03</span><b>진행·막힘</b><strong>${active}</strong><small>현재 운영 중</small></button><button onclick="go('tasks');taskStatus='done';render()" class="workflow-step"><span>04</span><b>성과 기록</b><strong>${done}</strong><small>완료 업무</small></button></div></div><div class="panel command-side"><div class="panel-header"><div><div class="panel-title">운영 원칙</div><div class="panel-desc">배정 판단에 반영되는 기준</div></div><span class="panel-pill">R&R RULES</span></div><div class="rule-list"><div><span>01</span><strong>직급·역량·경험</strong><small>업무에 맞는 후보 우선</small></div><div><span>02</span><strong>현재 업무부하</strong><small>배정 후 부하까지 계산</small></div><div><span>03</span><strong>담당자 만족도</strong><small>본인 응답을 다음 배정에 반영</small></div></div></div></div>`}
function scopedTeam(){
  const scope=dashboardTaskScope(),members=scope.members||[],tasks=scope.tasks||[];
  const avg=members.length?Math.round(members.reduce((sum,m)=>sum+calculatedWorkload(m),0)/members.length):0;
  const caution=members.filter(m=>calculatedWorkload(m)>=80).length;
  return `<section class="view">${heading('팀원 프로필','TEAM DIRECTORY',`${esc(scope.label||'전체')} 기준 구성원별 역량·경력·업무부하·담당 영역을 확인합니다.`,'<button class="btn secondary" onclick="openProfile()">내 프로필</button>')}<div class="team-summary"><div><strong>${members.length}</strong><span>조회 구성원</span></div><div><strong>${avg}%</strong><span>평균 업무부하</span></div><div><strong>${caution}</strong><span>부하 주의</span></div></div><div class="member-grid">${members.map(m=>{const owned=tasks.filter(t=>taskAssigneeNames(t).includes(m.name)),load=calculatedWorkload(m),tone=load>=80?'high':load>=60?'mid':'ok';return `<article class="member-card"><div class="member-top"><span class="profile-avatar small">${esc(m.name[0])}</span><div><h3>${esc(m.name)}</h3><p>${esc(m.level)} · 경력 ${m.experience}년</p></div><span class="member-status ${tone}">${load>=80?'주의':load>=60?'집중':'여유'}</span></div><div class="member-load"><div><span>자동 계산 업무부하</span><strong>${load}%</strong></div><div class="load-bar"><span class="${tone}" style="width:${Math.min(load,100)}%"></span></div></div><div class="member-capability"><label>가능 업무</label><span>${(m.types||[]).join(' · ')||'미설정'}</span></div><div class="chip-list">${m.skills.map(s=>`<span>${esc(s)}</span>`).join('')||'<span>역량 미설정</span>'}</div><div class="member-footer"><span>담당 업무 <b>${owned.length}건</b></span><button class="text-btn" onclick="openMemberProfile('${esc(m.name)}')">상세 보기 →</button></div></article>`}).join('')}</div></section>`;
}

// 현황판은 반복 설명 대신 핵심 수치와 상태별 건수만 보여준다.
function leaderSatisfactionPanel(){
  const scope=typeof window.getLeaderSatisfactionScope==='function'?window.getLeaderSatisfactionScope():null;
  if(!scope)return '';
  const memberNames=new Set((scope.members||[]).map(m=>m.name));
  const responses=data.satisfaction.filter(item=>memberNames.has(item.owner));
  const total=responses.length;
  const ratio=(value)=>total?Math.round(value/total*100):0;
  const fit=ratio(responses.filter(item=>item.fit==='적절').length);
  const load=ratio(responses.filter(item=>item.load==='과다').length);
  return `<section class="panel leader-satisfaction-panel"><div class="panel-header"><div><div class="panel-title">구성원 업무만족도</div><div class="panel-desc">${esc(scope.label)} ${scope.role==='team'?'전체 팀원':'그룹원'}의 응답 통계</div></div><span class="panel-pill">LEADER ONLY</span></div><div class="mini-stats"><div><strong>${total}</strong><small>응답 수</small></div><div><strong>${fit}%</strong><small>적절 응답</small></div><div><strong>${load}%</strong><small>과다 응답</small></div></div></section>`;
}

function dashboardTaskScope(){
  if(typeof window.getDashboardTaskScope==='function')return window.getDashboardTaskScope();
  return {tasks:data.tasks,members:data.members,label:'전체'};
}

function scopedCompactDashboard(){
  const scope=dashboardTaskScope(),tasks=scope.tasks||[],total=tasks.length||1;
  const assigned=tasks.filter(t=>t.status!=='unassigned'&&t.owner!=='미정').length;
  const pending=tasks.filter(t=>t.status==='unassigned').length;
  const active=tasks.filter(t=>['assigned','in_progress','blocked'].includes(t.status)).length;
  const done=tasks.filter(t=>t.status==='done').length;
  const blocked=tasks.filter(t=>t.status==='blocked').length;
  const rate=Math.round(assigned/total*100)||0,pct=value=>Math.round(value/total*100)||0;
  const statusLink=(status,label,count,tone='')=>`<button class="compact-status ${tone}" onclick="go('tasks');taskStatus='${status}';render()"><span>${label}</span><strong>${count}</strong><small>${pct(count)}%</small></button>`;
  return `<section class="view dashboard-view compact-dashboard"><div class="compact-dashboard-head"><div><span class="eyebrow">WORK STATUS</span><h1>업무현황판</h1><small class="dashboard-scope-label">${esc(scope.label||'전체')} 기준</small></div><button class="btn" onclick="go('tasks');setTimeout(openTaskForm,0)">+ 업무 등록</button></div><div class="compact-kpis"><article class="compact-kpi"><span>전체 업무</span><strong>${tasks.length}</strong><small>건</small></article><article class="compact-kpi accent"><span>담당 배정률</span><strong>${rate}</strong><small>%</small><i style="width:${Math.min(rate,100)}%"></i></article><article class="compact-kpi"><span>진행 중</span><strong>${active}</strong><small>건</small></article><article class="compact-kpi"><span>완료</span><strong>${done}</strong><small>건</small></article></div><div class="compact-grid"><article class="panel compact-status-panel"><div class="compact-panel-head"><h2>업무 상태</h2><button class="text-btn" onclick="go('tasks')">전체 보기 →</button></div><div class="compact-status-grid">${statusLink('unassigned','미배정',pending,'warning')}${statusLink('assigned','배정 완료',tasks.filter(t=>t.status==='assigned').length)}${statusLink('in_progress','진행 중',tasks.filter(t=>t.status==='in_progress').length,'active')}${statusLink('blocked','막힘',blocked,'danger')}${statusLink('done','완료',done,'done')}</div></article><article class="panel compact-summary-panel"><div class="compact-panel-head"><h2>요약</h2><span class="compact-total">${scope.members?.length||0}명</span></div><div class="compact-summary-row"><span>미배정 업무</span><strong>${pending}건</strong></div><div class="compact-summary-row"><span>완료율</span><strong>${pct(done)}%</strong></div><div class="compact-summary-row"><span>주의 업무</span><strong class="${blocked?'danger-text':''}">${blocked}건</strong></div></article></div></section>`;
}

