// 기존 상세형 대시보드 대신 요약형 현황판을 사용한다.
function canLeaderFeedback(task){
  if(task?.status!=='done'||!['leader','groupLeader'].includes(data.currentUserRole))return false;
  const scope=typeof window.getDashboardTaskScope==='function'?window.getDashboardTaskScope():null;
  return !scope||scope.tasks.some(item=>item.id===task.id);
}

function addLeaderFeedback(taskId){
  const task=data.tasks.find(item=>item.id===taskId);if(!task||!canLeaderFeedback(task))return;
  const comment=String(document.querySelector('#leaderFeedbackForm textarea')?.value||'').trim();
  if(!comment)return toast('피드백 내용을 입력해주세요.');
  if(!Array.isArray(task.leaderFeedback))task.leaderFeedback=[];
  task.leaderFeedback.push({id:Date.now(),taskId,author:currentUserName(),role:data.currentUserRole,comment,createdAt:today});
  save();toast('완료 업무 피드백을 저장했습니다.');openTaskDetail(taskId);
}

function enhanceTaskDetailWithFeedback(taskId){
  const task=data.tasks.find(item=>item.id===taskId),modal=document.querySelector('.detail-modal');if(!task||!modal||task.status!=='done')return;
  const feedbacks=Array.isArray(task.leaderFeedback)?task.leaderFeedback:[];
  const section=document.createElement('div');section.className='detail-section leader-feedback-section';
  section.innerHTML=`<div class="detail-section-head"><label>리더 피드백</label><small>완료 업무에 남긴 피드백은 담당자가 확인할 수 있습니다.</small></div>${feedbacks.map(item=>`<div class="leader-feedback-item"><strong>${esc(item.author)}</strong><small>${item.createdAt}</small><p>${esc(item.comment)}</p></div>`).join('')||'<div class="empty feedback-empty">아직 등록된 피드백이 없습니다.</div>'}${canLeaderFeedback(task)?'<form id="leaderFeedbackForm" class="leader-feedback-form"><textarea placeholder="완료된 업무에 대한 피드백을 남겨주세요."></textarea><button class="btn" type="submit">피드백 저장</button></form>':''}`;
  const actions=modal.querySelector('.modal-actions');modal.insertBefore(section,actions||null);
  const form=section.querySelector('#leaderFeedbackForm');if(form)form.onsubmit=e=>{e.preventDefault();addLeaderFeedback(taskId)};
}

const baseOpenTaskDetail=openTaskDetail;
openTaskDetail=function(taskId){baseOpenTaskDetail(taskId);enhanceTaskDetailWithFeedback(taskId)};

const baseOpenAssignModal=openAssignModal;
openAssignModal=function(taskId){
  if(!canManageAssignments())return toast('팀장 또는 그룹장만 담당자를 조정할 수 있습니다.');
  baseOpenAssignModal(taskId);
  const form=document.querySelector('#manualAssignForm');if(!form)return;
  const task=data.tasks.find(item=>item.id===taskId),multi=!!task&&isMultiTask(task);
  form.dataset.assignmentMode=multi?'multi':'single';
  form.querySelectorAll('input[name="assigneeChoice"]').forEach(input=>{input.type=multi?'checkbox':'radio'});
  const modeNote=form.querySelector('.assignment-mode-note span');if(modeNote)modeNote.textContent=multi?'첫 번째 선택 인원이 주담당자가 됩니다.':'단독 담당 업무는 한 명만 선택할 수 있습니다.';
  const labels=[...form.querySelectorAll('.assign-candidate')];
  labels.forEach((label,index)=>{const checkbox=label.querySelector('input[name="assigneeChoice"]');if(!checkbox)return;const select=document.createElement('select');select.className='assignee-priority';select.name='assigneePriority';select.dataset.name=checkbox.value;for(let n=1;n<=labels.length;n++){const option=document.createElement('option');option.value=n;option.textContent=`우선순위 ${n}`;if(n===index+1)option.selected=true;select.appendChild(option)}label.appendChild(select)});
  form.addEventListener('submit',event=>{event.preventDefault();event.stopImmediatePropagation();const selected=[...form.querySelectorAll('input[name="assigneeChoice"]:checked')];if(!selected.length)return toast('담당자를 한 명 이상 선택해주세요.');const names=selected.map(input=>({name:input.value,priority:Number([...form.querySelectorAll('select[name="assigneePriority"]')].find(select=>select.dataset.name===input.value)?.value)||999})).sort((a,b)=>a.priority-b.priority||a.name.localeCompare(b.name)).map(item=>item.name);confirmAssignTask(taskId,names)},true);
}

function canManageAssignments(){return ['admin','leader','groupLeader'].includes(data.currentUserRole)}
function hideMemberAssignmentControls(){
  if(canManageAssignments())return;
  document.querySelectorAll('.assign-actions,.manual-assign-btn').forEach(node=>node.remove());
}
const baseConfirmAssignTask=confirmAssignTask;
confirmAssignTask=function(taskId,names){if(!canManageAssignments())return toast('팀장 또는 그룹장만 담당자를 조정할 수 있습니다.');return baseConfirmAssignTask(taskId,names)};

