// 업무 변경 권한·상태 이력·중단 상태를 업무 상세 흐름에 통합한다.
const GOVERNANCE_STATUS_LABELS={paused:'업무 중단'};
const baseGovernanceStatusLabel=statusLabel;
statusLabel=function(status){return GOVERNANCE_STATUS_LABELS[status]||baseGovernanceStatusLabel(status)};
const GOVERNANCE_STATUSES=['unassigned','assigned','in_progress','blocked','paused','done'];
function taskIsInUserScope(task){if(!task)return false;if(isAdminUser())return true;const scope=typeof window.getDashboardTaskScope==='function'?window.getDashboardTaskScope():null;return !!scope?.tasks?.some(item=>item.id===task.id)}
function canEditTask(task){if(!task)return false;if(isAdminUser())return true;if(['leader','groupLeader'].includes(data.currentUserRole))return taskIsInUserScope(task);const user=currentUserName();return task.createdBy===user||taskAssigneeNames(task).includes(user)}
function canDeleteTask(task){if(!task||task.status==='done')return false;if(isAdminUser())return true;if(['leader','groupLeader'].includes(data.currentUserRole))return taskIsInUserScope(task);return task.createdBy===currentUserName()}
function taskHistoryEntries(task){if(Array.isArray(task?.statusHistory)&&task.statusHistory.length)return task.statusHistory;return data.history.filter(item=>item.taskId===task?.id&&item.kind==='status').map(item=>({from:item.previousStatus,to:item.newStatus,changedAt:item.changedAt,changedBy:item.changedBy||'시스템',reason:item.reason||''}))}
function governanceTime(value){if(!value)return '기록 없음';const date=new Date(value);return Number.isNaN(date.getTime())?String(value):date.toLocaleString('ko-KR',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}
function taskEditButton(id){const task=data.tasks.find(item=>item.id===id);if(!canEditTask(task)&&!canDeleteTask(task))return '';return `<span class="task-governance-actions">${canEditTask(task)?`<button class="task-edit-btn" onclick="event.stopPropagation();openTaskEdit(${id})">수정</button>`:''}${canDeleteTask(task)?`<button class="task-delete-btn" onclick="event.stopPropagation();removeTask(${id})">삭제</button>`:''}</span>`}
function openTaskEdit(id){const task=data.tasks.find(item=>item.id===id);if(!canEditTask(task))return toast('현재 직책으로는 이 업무를 수정할 수 없습니다.');const collaborators=(task.collaborators||[]).join(', ');$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal task-modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><p class="eyebrow">EDIT WORK ITEM</p><h2>업무 내용 수정</h2><p class="modal-help">${esc(task.title)} · 수정자 ${esc(currentUserName())}</p><form id="taskEditForm" class="modal-form"><div class="form-grid"><div class="field full-field"><label>업무명 <em>*</em></label><input name="title" required value="${esc(task.title)}"></div><div class="field full-field"><label>업무 설명</label><textarea name="description" placeholder="업무 목적과 주요 결과물을 적어주세요.">${esc(task.description||'')}</textarea></div><div class="field"><label>업무 종류</label><select name="taskType">${TASK_TYPES.map(type=>`<option ${task.taskType===type?'selected':''}>${type}</option>`).join('')}</select></div><div class="field"><label>업무 난이도</label><select name="difficulty">${TASK_LEVELS.map(level=>`<option ${task.difficulty===level?'selected':''}>${level}</option>`).join('')}</select></div><div class="field"><label>필요 직급</label><select name="level">${TASK_LEVELS.map(level=>`<option ${task.requiredLevel===level?'selected':''}>${level}</option>`).join('')}</select></div><div class="field"><label>최소 경력(년)</label><input name="experience" type="number" min="0" value="${Number(task.minExperience)||0}"></div><div class="field"><label>예상 소요시간</label><input name="hours" type="number" min="1" value="${Number(task.estimatedHours)||8}"></div><div class="field"><label>기한</label><input name="due" type="date" value="${esc(task.due||'')}"></div><div class="field full-field"><label>협업 조직</label><input name="collaborators" value="${esc(collaborators)}" placeholder="쉼표로 구분"></div></div><div class="modal-actions"><button type="button" class="btn secondary" onclick="closeModal()">취소</button><button class="btn" type="submit">수정 내용 저장</button></div></form></section></div>`;$('#taskEditForm').onsubmit=event=>{event.preventDefault();const form=new FormData(event.target),nextTitle=String(form.get('title')||'').trim();if(!nextTitle)return toast('업무명을 입력해주세요.');const before=task.title;task.title=nextTitle;task.description=String(form.get('description')||'').trim();task.taskType=String(form.get('taskType')||task.taskType);task.difficulty=String(form.get('difficulty')||task.difficulty);task.requiredLevel=String(form.get('level')||task.requiredLevel);task.minExperience=Math.max(0,Number(form.get('experience'))||0);task.estimatedHours=Math.max(1,Number(form.get('hours'))||8);task.due=String(form.get('due')||'');task.collaborators=String(form.get('collaborators')||'').split(',').map(value=>value.trim()).filter(Boolean);task.updatedAt=new Date().toISOString();task.updatedBy=currentUserName();data.history.push({id:Date.now(),kind:'edit',taskId:task.id,taskTitle:task.title,changedAt:task.updatedAt,changedBy:currentUserName(),reason:before===task.title?'업무 내용 수정':'업무명 및 내용 수정'});save();closeModal();toast('업무 내용을 수정했습니다.');render()}}
removeTask=function(id){const task=data.tasks.find(item=>item.id===id);if(!canDeleteTask(task))return toast('현재 직책으로는 이 업무를 삭제할 수 없습니다.');if(!confirm('이 업무를 삭제할까요? 삭제 후에는 복구할 수 없습니다.'))return;data.history.push({id:Date.now(),kind:'delete',taskId:id,taskTitle:task.title,changedAt:new Date().toISOString(),changedBy:currentUserName(),reason:'업무 삭제'});data.tasks=data.tasks.filter(item=>item.id!==id);save();closeModal();toast('업무를 삭제했습니다.');render()};
saveStatusChange=function(id,status,reason){const task=data.tasks.find(item=>item.id===id);if(!task||!canEditTask(task))return toast('현재 직책으로는 이 업무 상태를 변경할 수 없습니다.');if(!GOVERNANCE_STATUSES.includes(status))return toast('지원하지 않는 업무 상태입니다.');const old=task.status,cleanReason=String(reason||'').trim();if(old===status){closeModal();return}if(!cleanReason)return toast('상태 변경 사유를 입력해야 저장할 수 있습니다.');const changedAt=new Date().toISOString(),entry={id:Date.now(),from:old,to:status,changedAt,changedBy:currentUserName(),reason:cleanReason};if(!Array.isArray(task.statusHistory))task.statusHistory=[];task.statusHistory.push(entry);task.status=status;data.history.push({id:Date.now()+1,kind:'status',taskId:id,taskTitle:task.title,previousStatus:old,newStatus:status,reason:cleanReason,changedBy:currentUserName(),changedAt});syncComputedWorkloads();save();closeModal();toast(`${statusLabel(status)} 상태로 변경했습니다.`);render()};
openStatusModal=function(id,status){const task=data.tasks.find(item=>item.id===id);if(!task||!canEditTask(task))return toast('현재 직책으로는 이 업무 상태를 변경할 수 없습니다.');const history=taskHistoryEntries(task).slice(-8).reverse();$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal status-modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><p class="eyebrow">UPDATE STATUS</p><h2>업무 상태 변경</h2><p class="modal-help">${esc(task.title)} · 현재 ${statusLabel(task.status)}</p><form id="statusForm" class="modal-form"><div class="field"><label>변경할 상태</label><select name="status">${GOVERNANCE_STATUSES.map(value=>`<option value="${value}" ${status===value?'selected':''}>${statusLabel(value)}</option>`).join('')}</select></div><div class="field"><label>변경 사유 <em>* 필수</em></label><textarea name="reason" required placeholder="예: 검토 보류, 우선순위 변경, 결과물 확인 완료"></textarea><small class="field-help">사유를 입력해야 상태 변경 이력이 저장됩니다.</small></div><div class="status-history-mini"><label>최근 상태 변경</label>${history.map(item=>`<p><b>${statusLabel(item.from)}</b> → <b>${statusLabel(item.to)}</b><small>${governanceTime(item.changedAt)} · ${esc(item.changedBy||'시스템')}</small></p>`).join('')||'<p class="empty">아직 상태 변경 이력이 없습니다.</p>'}</div><div class="modal-actions"><button type="button" class="btn secondary" onclick="closeModal()">취소</button><button class="btn" type="submit">이력과 함께 저장</button></div></form></section></div>`;$('#statusForm').onsubmit=event=>{event.preventDefault();const form=new FormData(event.target);saveStatusChange(id,String(form.get('status')),String(form.get('reason')||''))}}
const governanceBaseOpenTaskDetail=openTaskDetail;
openTaskDetail=function(id){governanceBaseOpenTaskDetail(id);const task=data.tasks.find(item=>item.id===id),modal=document.querySelector('.detail-modal');if(!task||!modal)return;const statusSection=modal.querySelector('.status-actions')?.closest('.detail-section');if(statusSection){if(canEditTask(task))statusSection.querySelector('.status-actions').innerHTML=GOVERNANCE_STATUSES.map(value=>`<button class="status-choice ${value===task.status?'selected':''}" onclick="changeTaskStatus(${id},'${value}')">${statusLabel(value)}</button>`).join('');else statusSection.remove()}const history=taskHistoryEntries(task);const historySection=document.createElement('div');historySection.className='detail-section task-status-history';historySection.innerHTML=`<div class="detail-section-head"><label>상태 변경 이력</label><small>상태가 바뀐 시각과 변경자를 확인합니다.</small></div>${history.slice().reverse().map(item=>`<div class="task-history-row"><span class="history-transition"><b>${statusLabel(item.from)}</b><i>→</i><b>${statusLabel(item.to)}</b></span><span>${esc(item.changedBy||'시스템')}</span><small>${governanceTime(item.changedAt)}${item.reason?' · '+esc(item.reason):''}</small></div>`).join('')||'<div class="empty">아직 상태 변경 이력이 없습니다.</div>'}`;const actions=modal.querySelector('.modal-actions');if(actions){modal.insertBefore(historySection,actions);if(canEditTask(task)){const edit=document.createElement('button');edit.className='btn secondary';edit.textContent='업무 수정';edit.onclick=()=>openTaskEdit(id);actions.insertBefore(edit,actions.firstChild)}if(canDeleteTask(task)){const remove=document.createElement('button');remove.className='btn danger';remove.textContent='업무 삭제';remove.onclick=()=>removeTask(id);actions.insertBefore(remove,actions.firstChild)}}};
function decorateTaskGovernanceUI(){document.querySelectorAll('#taskStatusFilter').forEach(select=>{if(!select.querySelector('option[value="paused"]'))select.insertAdjacentHTML('beforeend','<option value="paused">업무 중단</option>')});document.querySelectorAll('.status-select').forEach(select=>{if(!select.querySelector('option[value="paused"]'))select.insertAdjacentHTML('beforeend','<option value="paused">업무 중단</option>');const task=data.tasks.find(item=>item.title===select.getAttribute('aria-label')?.replace(/ 상태$/,''));if(task&&!canEditTask(task))select.disabled=true});document.querySelectorAll('.task-tile').forEach(tile=>{const title=tile.querySelector('h3')?.textContent.trim(),task=data.tasks.find(item=>item.title===title);if(task&&!tile.querySelector('.task-governance-actions')&&(canEditTask(task)||canDeleteTask(task)))tile.querySelector('.task-head')?.insertAdjacentHTML('beforeend',taskEditButton(task.id))})}
if(!document.getElementById('taskGovernanceStyles')){const style=document.createElement('style');style.id='taskGovernanceStyles';style.textContent='.task-governance-actions{display:inline-flex;gap:4px;margin-left:auto}.task-edit-btn,.task-delete-btn{border:1px solid var(--line);border-radius:6px;background:#fff;color:var(--blue);padding:5px 7px;font:700 10px inherit;cursor:pointer}.task-delete-btn{color:#b43b3b;border-color:#efcaca}.task-history-row{display:grid;grid-template-columns:auto auto 1fr;gap:7px;align-items:center;padding:9px 0;border-bottom:1px solid var(--line);font-size:11px}.task-history-row:last-child{border-bottom:0}.history-transition{display:inline-flex;gap:5px;align-items:center}.history-transition i{color:var(--muted);font-style:normal}.task-history-row small{color:var(--muted);text-align:right}.status-select.paused,.status-choice.paused{border-color:#d18d3a;background:#fff8ec}.btn.danger{color:#b43b3b;border-color:#efcaca;background:#fff}.task-status-history{margin-top:4px}@media(max-width:650px){.task-history-row{grid-template-columns:1fr;gap:3px}.task-history-row small{text-align:left}.task-governance-actions{width:100%;margin:5px 0 0}.task-head{flex-wrap:wrap}}';document.head.appendChild(style)}
const taskGovernanceObserver=new MutationObserver(decorateTaskGovernanceUI);taskGovernanceObserver.observe(document.body,{childList:true,subtree:true});decorateTaskGovernanceUI();
function bindReliableNavigation(){document.querySelectorAll('.nav-item').forEach(item=>{if(item.dataset.reliableNavBound)return;item.dataset.reliableNavBound='true';item.hidden=item.dataset.view==='tasks'?false:item.hidden;item.onclick=()=>{const view=item.dataset.view;if(typeof window.go==='function')window.go(view);else go(view)}})}
const reliableNavigationObserver=new MutationObserver(bindReliableNavigation);reliableNavigationObserver.observe(document.body,{childList:true,subtree:true});bindReliableNavigation();
function currentUserVisibleTasks(){const scoped=typeof window.getDashboardTaskScope==='function'?window.getDashboardTaskScope():null;if(scoped?.tasks)return scoped.tasks;const user=typeof currentUserName==='function'?currentUserName():data.currentUser;return data.tasks.filter(task=>taskAssigneeNames(task).includes(user)||task.createdBy===user)}
function syncTaskNavCount(){const node=document.querySelector('#navTaskCount');if(!node)return;const count=currentUserVisibleTasks().filter(task=>['unassigned','in_progress','blocked'].includes(task.status)).length;if(node.textContent!==String(count))node.textContent=String(count);node.title='배정 전·진행 중·막힘 업무'}
const taskNavCountObserver=new MutationObserver(syncTaskNavCount);taskNavCountObserver.observe(document.body,{childList:true,subtree:true});syncTaskNavCount();

// 로그인 사용자 기준 프로필과 기간별 업무부하 조회
function profileMember(){const name=typeof currentUserName==='function'?currentUserName():data.currentUser;return data.members.find(member=>member.name===name)||data.members[0]}
function profileDate(value,fallback){const date=new Date(`${value||fallback}T00:00:00`);return Number.isNaN(date.getTime())?new Date(`${fallback}T00:00:00`):date}
function profileISO(date){return date.toISOString().slice(0,10)}
function profileBusinessDays(start,end){const days=[];for(let cursor=new Date(start);cursor<=end;cursor.setDate(cursor.getDate()+1)){if(cursor.getDay()!==0&&cursor.getDay()!==6)days.push(profileISO(cursor))}return days}
function profileTaskRange(task){const start=String(task.startedAt||task.createdAt||today).slice(0,10);const end=String(task.completedAt||task.due||today).slice(0,10);return {start:start||today,end:end&&end>=start?end:start}}
function profileWorkloadData(member,from,to){const days=[];for(let cursor=new Date(from);cursor<=to;cursor.setDate(cursor.getDate()+1))days.push(profileISO(cursor));const business=profileBusinessDays(from,to),capacityPerDay=(Number(member.capacityHours)||24)*Math.max(.25,Number(member.availability)||1)/5;const tasks=data.tasks.filter(task=>task.status!=='unassigned'&&taskAssigneeNames(task).includes(member.name));const rows=days.map(date=>{const active=tasks.filter(task=>{const range=profileTaskRange(task);return date>=range.start&&date<=range.end});const hours=active.reduce((sum,task)=>{const range=profileTaskRange(task),taskDays=Math.max(1,profileBusinessDays(profileDate(range.start,date),profileDate(range.end,date)).length);return sum+(Number(task.estimatedHours)||0)/Math.max(1,taskAssigneeNames(task).length)/taskDays},0);return {date,hours,rate:business.includes(date)&&capacityPerDay?Math.round(hours/capacityPerDay*100):0,tasks:active}});const workRows=rows.filter(row=>business.includes(row.date));return {rows,business,capacityPerDay,average:workRows.length?Math.round(workRows.reduce((sum,row)=>sum+row.rate,0)/workRows.length):0,peak:workRows.reduce((max,row)=>Math.max(max,row.rate),0),attention:workRows.filter(row=>row.rate>=80).length,tasks}}
function profileDateLabel(value){const date=profileDate(value,today);return `${date.getMonth()+1}.${String(date.getDate()).padStart(2,'0')} (${['일','월','화','수','목','금','토'][date.getDay()]})`}
function profileDepartment(member){return data.departments?.find(department=>department.id===member?.departmentId)?.name||'소속 미지정'}
function profileRoleLabel(){return window.RR_AUTH?.roleLabel?.(data.currentUserRole)||({admin:'시스템 관리자',leader:'팀장',groupLeader:'그룹장',member:'팀원'}[data.currentUserRole]||'팀원')}
function renderProfileWorkload(){const modal=document.querySelector('#profileModal');if(!modal)return;const member=data.members.find(item=>String(item.id)===String(modal.dataset.memberId))||profileMember();const fromInput=modal.querySelector('[name="profileFrom"]'),toInput=modal.querySelector('[name="profileTo"]');let from=profileDate(fromInput?.value,today),to=profileDate(toInput?.value,today);if(from>to){const swap=from;from=to;to=swap;fromInput.value=profileISO(from);toInput.value=profileISO(to)}const workloadData=profileWorkloadData(member,from,to),result=modal.querySelector('#profileWorkloadResult');if(!result)return;const teamScope=['leader','groupLeader'].includes(data.currentUserRole)&&typeof window.getDashboardTaskScope==='function'?window.getDashboardTaskScope():null;const peers=teamScope?.members||[];const peerSummary=peers.length?`<div class="profile-team-summary"><div class="profile-section-heading"><div><strong>조직 구성원 업무부하</strong><small>선택한 기간의 평균·최대 부하를 비교합니다.</small></div><span>${peers.length}명</span></div><div class="profile-peer-grid">${peers.map(peer=>{const stats=profileWorkloadData(peer,from,to),tone=stats.peak>=100?'high':stats.peak>=80?'mid':'ok';return `<button type="button" class="profile-peer-card ${peer.id===member.id?'selected':''}" data-profile-member="${peer.id}"><span>${esc(peer.name)}</span><small>${esc(peer.level)} · ${esc(profileDepartment(peer))}</small><b class="${tone}">${stats.average}%</b><em>최대 ${stats.peak}%</em></button>`}).join('')}</div></div>`:'';result.innerHTML=`<div class="profile-load-summary"><div><span>기간 평균</span><strong>${workloadData.average}%</strong></div><div><span>최대 부하</span><strong>${workloadData.peak}%</strong></div><div><span>주의 일수</span><strong>${workloadData.attention}일</strong></div><div><span>계산 업무</span><strong>${workloadData.tasks.length}건</strong></div></div>${peerSummary}<div class="profile-section-heading"><div><strong>${esc(member.name)} 일별 업무부하</strong><small>주당 가능시간 ${Number(member.capacityHours)||24}시간 · 가용률 ${Math.round(Math.max(.25,Number(member.availability)||1)*100)}%</small></div></div><div class="profile-load-chart">${workloadData.rows.map(row=>`<div class="profile-load-row ${row.rate>=80?'attention':''}"><span>${profileDateLabel(row.date)}</span><div class="profile-load-track"><i style="width:${Math.min(100,row.rate)}%"></i></div><b>${row.rate}%</b><small>${row.hours.toFixed(1)}시간</small></div>`).join('')}</div><div class="profile-workload-note">업무 예상시간을 업무 기간의 평일 수와 공동 담당자 수로 나눠 일별 부하를 계산합니다. 주말은 부하율 계산에서 제외합니다.</div>`;result.querySelectorAll('[data-profile-member]').forEach(button=>button.onclick=()=>{modal.dataset.memberId=button.dataset.profileMember;renderProfileWorkload()})}
openProfile=function(){const member=profileMember();const owned=data.tasks.filter(task=>taskAssigneeNames(task).includes(member.name));const start=new Date(profileDate(today,today));start.setDate(start.getDate()-13);const teamView=['leader','groupLeader'].includes(data.currentUserRole)&&typeof window.getDashboardTaskScope==='function';const scope=teamView?window.getDashboardTaskScope():null;$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal profile-modal profile-detail-modal" id="profileModal" data-member-id="${member.id}" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><div class="profile-hero"><span class="profile-avatar">${esc(member.name[0])}</span><div><p class="eyebrow">MY PROFILE</p><h2>${esc(member.name)}</h2><p>${esc(profileRoleLabel())} · ${esc(profileDepartment(member))} · ${member.experience||0}년 경력</p></div></div><div class="profile-grid"><div class="profile-block"><label>핵심 역량</label><div class="chip-list">${(member.skills||[]).map(skill=>`<span>${esc(skill)}</span>`).join('')||'<span>등록된 역량 없음</span>'}</div></div><div class="profile-block"><label>가능 업무</label><strong>${(member.types||[]).length}종</strong><small>${(member.types||[]).map(type=>esc(type)).join(' · ')||'등록된 업무 없음'}</small></div><div class="profile-block"><label>현재 자동 계산 업무부하</label><strong>${calculatedWorkload(member)}%</strong><small>배정 예상시간·가용률 기준</small></div><div class="profile-block"><label>담당 업무</label><strong>${owned.length}건</strong><small>${owned.slice(0,3).map(task=>esc(task.title)).join(' · ')||'현재 담당 업무 없음'}</small></div></div><div class="profile-workload-toolbar"><div><strong>기간별 업무부하</strong><small>날짜별 업무량을 확인합니다.</small></div><label>시작일<input type="date" name="profileFrom" value="${profileISO(start)}"></label><label>종료일<input type="date" name="profileTo" value="${today}"></label></div><div id="profileWorkloadResult"></div>${scope?.members?.length?'<div class="profile-access-note">조직장 권한으로 관리 조직 구성원의 업무부하를 함께 조회할 수 있습니다.</div>':''}<div class="modal-actions"><button class="btn secondary" onclick="closeModal()">닫기</button><button class="btn" onclick="go('tasks');closeModal()">내 담당 업무 보기</button></div></section></div>`;const modal=document.querySelector('#profileModal');modal.querySelectorAll('[name="profileFrom"],[name="profileTo"]').forEach(input=>input.onchange=renderProfileWorkload);renderProfileWorkload()}
function openNotifications(){const user=profileMember(),scope=['leader','groupLeader','admin'].includes(data.currentUserRole)&&typeof window.getDashboardTaskScope==='function'?window.getDashboardTaskScope():null;const tasks=scope?.tasks||data.tasks.filter(task=>taskAssigneeNames(task).includes(user.name));const notices=[...tasks.filter(task=>task.status==='blocked').map(task=>({title:'막힘 상태 업무',body:task.title})),...tasks.filter(task=>task.status==='unassigned').slice(0,5).map(task=>({title:'담당자 지정 필요',body:task.title})),...tasks.filter(task=>task.due&&task.due<=new Date(Date.now()+7*86400000).toISOString().slice(0,10)&&task.status!=='done').slice(0,5).map(task=>({title:'기한 임박 업무',body:`${task.title} · 마감 ${task.due}`}))];$('#modalRoot').innerHTML=`<div class="modal-backdrop" onclick="closeModal()"><section class="modal notification-modal" onclick="event.stopPropagation()"><button class="modal-close" onclick="closeModal()">×</button><p class="eyebrow">NOTIFICATIONS</p><h2>알림</h2><p class="modal-help">${esc(user.name)}님이 확인할 업무 알림입니다.</p><div class="notification-list">${notices.map(notice=>`<button type="button" onclick="go('tasks');closeModal()"><strong>${esc(notice.title)}</strong><span>${esc(notice.body)}</span></button>`).join('')||'<div class="empty">새로운 업무 알림이 없습니다.</div>'}</div><div class="modal-actions"><button class="btn secondary" onclick="closeModal()">닫기</button></div></section></div>`}
function syncHeaderIdentity(){const member=profileMember(),profile=document.querySelector('#profileBtn'),live=document.querySelector('.live-users');document.querySelectorAll('.auth-user-chip').forEach(node=>node.remove());if(profile&&member){const identity=`${member.id}:${data.currentUserRole||''}`;if(profile.dataset.identity!==identity){profile.dataset.identity=identity;profile.innerHTML=`<span class="profile-trigger-avatar">${esc(member.name[0])}</span><span class="profile-trigger-copy"><strong>${esc(member.name)}</strong><small>${esc(profileRoleLabel())}</small></span>`;profile.classList.add('profile-trigger');profile.title='내 프로필 열기';profile.setAttribute('aria-label',`${member.name} 프로필 열기`)}}if(live){const count=data.members?.length||0;if(live.dataset.memberCount!==String(count)){live.dataset.memberCount=String(count);live.innerHTML=`<span class="pulse"></span><span>구성원</span><b>${count}</b><span>명</span>`;live.title='현재 등록된 구성원 수'}}}
function bindProfileHeaderActions(){const profile=document.querySelector('#profileBtn'),notice=document.querySelector('.icon-btn[title="알림"]');syncHeaderIdentity();if(profile){profile.onclick=openProfile}if(notice){notice.onclick=openNotifications;notice.title='업무 알림';notice.setAttribute('aria-label','업무 알림 열기');if(!notice.querySelector('i')){const dot=document.createElement('i');dot.setAttribute('aria-hidden','true');notice.appendChild(dot)}}}
function enhanceGradeAndExperienceRanges(){document.querySelectorAll('select[name="level"]').forEach(select=>{if(select.dataset.rangeBound)return;const current=normalizeGrade(select.value),index=Math.max(0,GRADE_LEVELS.indexOf(current));select.dataset.rangeBound='true';select.value=current;select.hidden=true;const range=document.createElement('input');range.type='range';range.className='grade-range';range.min='0';range.max=String(GRADE_LEVELS.length-1);range.step='1';range.value=String(index);const output=document.createElement('output');output.className='range-value';output.textContent=current;range.oninput=()=>{const next=GRADE_LEVELS[Number(range.value)];select.value=next;output.textContent=next;select.dispatchEvent(new Event('change',{bubbles:true}))};select.after(range,output)});document.querySelectorAll('input[name="experience"]').forEach(input=>{if(input.dataset.rangeBound)return;input.dataset.rangeBound='true';input.type='range';input.classList.add('experience-range');input.min='0';input.max='20';input.step='1';input.value=String(Math.max(0,Math.min(20,Number(input.value)||0)));const output=document.createElement('output');output.className='range-value';output.textContent=`${input.value}년`;input.after(output);input.oninput=()=>{output.textContent=`${input.value}년`}})}
function enhanceDifficultyFields(){document.querySelectorAll('select[name="difficulty"]').forEach(select=>{if(select.dataset.difficultyBound)return;select.dataset.difficultyBound='true';const current=normalizeDifficulty(select.value);select.innerHTML=TASK_DIFFICULTIES.map(level=>`<option value="${level}" ${level===current?'selected':''}>${level}</option>`).join('')})}
const gradeRangeObserver=new MutationObserver(()=>{enhanceGradeAndExperienceRanges();enhanceDifficultyFields()});gradeRangeObserver.observe(document.body,{childList:true,subtree:true});enhanceGradeAndExperienceRanges();enhanceDifficultyFields();
if(!document.getElementById('gradeRangeStyles')){const style=document.createElement('style');style.id='gradeRangeStyles';style.textContent='.grade-range,.experience-range{width:100%;accent-color:var(--blue);cursor:pointer}.range-value{display:inline-block;margin-top:5px;color:var(--blue);font-size:12px;font-weight:800}.field:has(>.grade-range),.field:has(>.experience-range){align-content:start}';document.head.appendChild(style)}
const profileHeaderObserver=new MutationObserver(bindProfileHeaderActions);profileHeaderObserver.observe(document.body,{childList:true,subtree:true});bindProfileHeaderActions();

// 업무 필터는 상태·검색·마감·부하 조건을 같은 파이프라인에서 평가한다.
function taskFilterStatusMatch(task,status=taskStatus){return status==='all'||(status==='active'?['in_progress','blocked'].includes(task.status):task.status===status)}
function taskFilterSearchText(task){return [task.title,task.description,task.taskType,task.difficulty,task.requiredLevel,task.owner,...taskAssigneeNames(task),...(task.requiredSkills||[]),...(task.collaborators||[])].filter(Boolean).join(' ').toLowerCase()}
function taskFilterDueMatch(task,due=taskDueFilter){if(due==='all')return true;if(due==='nodue')return !task.due;if(!task.due)return false;const days=Math.ceil((new Date(`${task.due}T00:00:00`)-new Date(`${today}T00:00:00`))/86400000);return due==='overdue'?days<0:due==='week'?days>=0&&days<=7:true}
function taskFilterLoadMatch(task,load=taskLoadFilter){if(load==='all')return true;const names=taskAssigneeNames(task);if(load==='unassigned')return !names.length;return load==='risk'&&names.some(name=>calculatedWorkload(data.members.find(member=>member.name===name))>=80)}
function taskFilterMatches(task){const query=taskQuery.trim().toLowerCase();return taskFilterStatusMatch(task)&&(!query||taskFilterSearchText(task).includes(query))&&(taskOwner==='all'||taskAssigneeNames(task).includes(taskOwner))&&(taskTypeFilter==='all'||task.taskType===taskTypeFilter)&&taskFilterDueMatch(task)&&taskFilterLoadMatch(task)}
function taskFilterSort(a,b){if(taskSort==='new')return Number(b.id)-Number(a.id);if(taskSort==='owner')return taskAssigneeLabel(a).localeCompare(taskAssigneeLabel(b),'ko');return (a.due||'9999-99-99').localeCompare(b.due||'9999-99-99')||Number(b.id)-Number(a.id)}
filteredTasks=function(){return data.tasks.filter(taskFilterMatches).sort(taskFilterSort)};
clearTaskFilters=function(){taskQuery='';taskStatus='all';taskOwner='all';taskSort='due';taskTypeFilter='all';taskDueFilter='all';taskLoadFilter='all';render()};

function setupRoleTaskFilters(){
  const view=[...document.querySelectorAll('.view')].find(node=>node.querySelector('.board-summary')&&node.querySelector('.task-grid'));
  const grid=view?.querySelector('.task-grid');if(!view||!grid||view.dataset.filterPipelineBound)return;
  view.dataset.filterPipelineBound='true';
  const panel=view.querySelector('.task-filter-explorer')||document.createElement('section');panel.className='task-filter-explorer task-filter-pipeline';
  panel.innerHTML=`<div class="task-filter-head"><div><strong>업무 탐색</strong><span>검색어와 조건을 함께 적용해 필요한 업무만 확인합니다.</span></div><button type="button" class="text-btn" data-filter-reset>전체 초기화</button></div><div class="task-quick-filters"><button type="button" data-role-status="all">전체</button><button type="button" data-role-status="unassigned">담당자 대기</button><button type="button" data-role-status="assigned">배정 완료</button><button type="button" data-role-status="in_progress">진행 중</button><button type="button" data-role-status="blocked">막힘</button><button type="button" data-role-status="done">완료</button></div><div class="task-filter-fields"><label>업무 종류<select data-filter="type"><option value="all">전체 업무 종류</option>${[...new Set(data.tasks.map(task=>task.taskType).filter(Boolean))].sort().map(type=>`<option value="${esc(type)}">${esc(type)}</option>`).join('')}</select></label><label>담당자<select data-filter="owner"><option value="all">전체 담당자</option>${data.members.map(member=>`<option value="${esc(member.name)}">${esc(member.name)}</option>`).join('')}</select></label><label>마감<select data-filter="due"><option value="all">전체 기한</option><option value="overdue">기한 초과</option><option value="week">7일 이내</option><option value="nodue">기한 미정</option></select></label><label>업무부하<select data-filter="load"><option value="all">전체 부하</option><option value="unassigned">담당자 미정</option><option value="risk">부하 80% 이상</option></select></label></div><input class="member-search-input role-filter-search" data-role-search type="search" placeholder="업무명, 설명, 담당자, 역량 검색" aria-label="업무 필터 검색"><div class="task-active-filter" data-role-count aria-live="polite"></div>`;
  if(!panel.parentElement)view.querySelector('.board-summary')?.after(panel);
  const cards=[...grid.querySelectorAll('.task-tile')].map(card=>({card,task:data.tasks.find(task=>task.title===card.querySelector('h3')?.textContent.trim())})).filter(item=>item.task);
  const refresh=()=>{const queryInput=panel.querySelector('[data-role-search]'),type=panel.querySelector('[data-filter="type"]'),owner=panel.querySelector('[data-filter="owner"]'),due=panel.querySelector('[data-filter="due"]'),load=panel.querySelector('[data-filter="load"]');if(queryInput)queryInput.value=taskQuery;type.value=taskTypeFilter;owner.value=taskOwner;due.value=taskDueFilter;load.value=taskLoadFilter;let visible=0;cards.forEach(({card,task})=>{const match=taskFilterMatches(task);card.hidden=!match;if(match)visible++});const active=[taskQuery,taskOwner!=='all'?`담당자: ${taskOwner}`:'',taskStatus!=='all'?`상태: ${taskStatus==='active'?'진행·막힘':statusLabel(taskStatus)}`:'',taskTypeFilter!=='all'?`종류: ${taskTypeFilter}`:'',taskDueFilter!=='all'?`마감 조건`:'',taskLoadFilter!=='all'?`부하 조건`:''].filter(Boolean);panel.querySelector('[data-role-count]').textContent=`${visible}개 표시 · ${active.length?active.join(' · '):'전체 업무'}`;panel.querySelectorAll('[data-role-status]').forEach(button=>button.classList.toggle('active',button.dataset.roleStatus===taskStatus))};
  panel.querySelector('[data-role-search]').oninput=event=>{taskQuery=event.target.value;refresh()};panel.querySelector('[data-filter="type"]').onchange=event=>{taskTypeFilter=event.target.value;refresh()};panel.querySelector('[data-filter="owner"]').onchange=event=>{taskOwner=event.target.value;refresh()};panel.querySelector('[data-filter="due"]').onchange=event=>{taskDueFilter=event.target.value;refresh()};panel.querySelector('[data-filter="load"]').onchange=event=>{taskLoadFilter=event.target.value;refresh()};panel.querySelector('[data-filter-reset]').onclick=()=>clearTaskFilters();panel.querySelectorAll('[data-role-status]').forEach(button=>button.onclick=()=>{taskStatus=button.dataset.roleStatus;refresh()});refresh();
}
roleTaskFilterObserver.disconnect();const improvedRoleTaskFilterObserver=new MutationObserver(setupRoleTaskFilters);improvedRoleTaskFilterObserver.observe(document.body,{childList:true,subtree:true});setupRoleTaskFilters();
const baseOpenMemberProfileForScope=openMemberProfile;openMemberProfile=function(name){const canViewOthers=['admin','leader','groupLeader'].includes(data.currentUserRole);if(!canViewOthers&&name!==currentUserName())return toast('개인 구성원은 본인 프로필만 조회할 수 있습니다.');return baseOpenMemberProfileForScope(name)};
if(!document.getElementById('profileWorkloadStyles')){const style=document.createElement('style');style.id='profileWorkloadStyles';style.textContent='.profile-detail-modal{max-width:760px}.profile-workload-toolbar{display:flex;align-items:flex-end;gap:12px;margin:20px 0 14px;padding:14px;border:1px solid var(--line);border-radius:10px;background:#f7fafc}.profile-workload-toolbar>div{flex:1}.profile-workload-toolbar strong,.profile-workload-toolbar small,.profile-section-heading strong,.profile-section-heading small{display:block}.profile-workload-toolbar small,.profile-section-heading small{color:var(--muted);font-size:10px;margin-top:4px}.profile-workload-toolbar label{display:grid;gap:5px;color:var(--muted);font-size:10px;font-weight:700}.profile-workload-toolbar input{border:1px solid var(--line);border-radius:6px;padding:8px;font:inherit;font-size:11px;color:var(--ink);background:#fff}.profile-load-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:18px}.profile-load-summary>div{padding:11px;border:1px solid var(--line);border-radius:9px;background:#fff}.profile-load-summary span,.profile-load-summary strong{display:block}.profile-load-summary span{color:var(--muted);font-size:10px}.profile-load-summary strong{color:var(--navy);font-size:20px;margin-top:5px}.profile-section-heading{display:flex;justify-content:space-between;align-items:flex-start;margin:16px 0 9px}.profile-section-heading>span{color:var(--muted);font-size:10px}.profile-load-chart{display:grid;gap:7px}.profile-load-row{display:grid;grid-template-columns:115px 1fr 40px 62px;gap:8px;align-items:center;font-size:10px}.profile-load-row>span{color:var(--muted)}.profile-load-track{height:8px;border-radius:8px;background:#edf2f5;overflow:hidden}.profile-load-track i{display:block;height:100%;border-radius:8px;background:var(--blue)}.profile-load-row.attention .profile-load-track i{background:#df8b4d}.profile-load-row b{text-align:right;color:var(--navy)}.profile-load-row small{text-align:right;color:var(--muted)}.profile-team-summary{border-top:1px solid var(--line);padding-top:12px;margin-top:5px}.profile-peer-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px}.profile-peer-card{display:grid;gap:3px;border:1px solid var(--line);border-radius:8px;background:#fff;padding:9px;text-align:left;cursor:pointer}.profile-peer-card.selected{border-color:var(--blue);box-shadow:0 0 0 2px rgba(15,76,129,.1)}.profile-peer-card span{font-weight:800;color:var(--navy);font-size:11px}.profile-peer-card small,.profile-peer-card em{color:var(--muted);font-size:9px;font-style:normal}.profile-peer-card b{font-size:17px;color:var(--blue)}.profile-peer-card b.mid{color:#c07d2d}.profile-peer-card b.high{color:#b94e4e}.profile-workload-note,.profile-access-note{margin-top:12px;color:var(--muted);font-size:10px;line-height:1.5}.profile-access-note{padding:9px 11px;border-radius:7px;background:#edf5f9;color:var(--blue)}.notification-list{display:grid;gap:8px}.notification-list button{display:grid;gap:4px;border:1px solid var(--line);border-radius:8px;background:#fff;padding:11px;text-align:left;cursor:pointer}.notification-list button:hover{border-color:#a9c9da;background:#f7fbfd}.notification-list strong{color:var(--navy);font-size:11px}.notification-list span{color:var(--muted);font-size:10px}@media(max-width:650px){.profile-workload-toolbar{align-items:stretch;flex-direction:column}.profile-load-summary{grid-template-columns:repeat(2,1fr)}.profile-peer-grid{grid-template-columns:repeat(2,1fr)}.profile-load-row{grid-template-columns:92px 1fr 35px;gap:6px}.profile-load-row small{display:none}}';document.head.appendChild(style)}
